function loadCustomEmotes(){
  try{
    const raw=localStorage.getItem('customEmoteConfig');
    if(raw){
      const arr=JSON.parse(raw);
      if(Array.isArray(arr)&&arr.length===8)return arr;
    }
  }catch(e){/* ignore */}
  return DEFAULT_EMOTE_DATA.map(e=>({...e}));
}
