/* ================================================================
   UI DIALOGS — Electron-compatible replacements for alert/confirm/prompt
================================================================ */
function showAlert(msg){
  const el=document.getElementById('uiFlash');
  el.textContent=msg;el.style.display='block';el.style.opacity='1';
  clearTimeout(el._t);
  el._t=setTimeout(()=>{el.style.opacity='0';setTimeout(()=>{el.style.display='none';},260);},3500);
}
const MAX_CHARGES=10;
function clampChargeValue(v){
  const n=parseInt(v);
  if(isNaN(n))return 0;
  return Math.max(0,Math.min(MAX_CHARGES,n));
}
function clampBrushValue(v){
  const n=parseInt(v,10);
  if(Number.isNaN(n))return 2;
  return Math.max(1,Math.min(40,n));
}
function hexToRgba(hex,alpha){
  const m=/^#?([\da-f]{2})([\da-f]{2})([\da-f]{2})$/i.exec((hex||'').trim());
  if(!m)return `rgba(99,102,241,${alpha})`;
  return `rgba(${parseInt(m[1],16)},${parseInt(m[2],16)},${parseInt(m[3],16)},${alpha})`;
}
function syncHostDrawControls(){
  drawBrushSize=clampBrushValue(drawBrushSizeEl?.value);
  drawStrokeColor=drawColorEl?.value||'#6366f1';
}
function syncGuestDrawControls(){
  guestBrushSize=clampBrushValue(guestBrushSizeEl?.value);
  guestStrokeColor=guestDrawColorEl?.value||'#818cf8';
}
function switchGuestTab(tabName){
  if(!guestTabMain||!guestTabDraw||!guestTabBtnMain||!guestTabBtnDraw)return;
  const next=(tabName==='draw'&&guestDrawEnabled)?'draw':'main';
  guestActiveTab=next;
  guestTabBtnMain.classList.toggle('active',next==='main');
  guestTabBtnDraw.classList.toggle('active',next==='draw');
  guestTabMain.classList.toggle('active',next==='main');
  guestTabDraw.classList.toggle('active',next==='draw');
  if(next!=='draw'){guestIsDrawing=false;guestCurrentDrawing=null;}
  drawAll();
}
function refreshGuestDrawAccess(){
  if(!guestTabBtnDraw||!guestTabDraw)return;
  guestTabBtnDraw.style.display=guestDrawEnabled?'':'none';
  guestTabDraw.style.display=guestDrawEnabled?'':'none';
  if(!guestDrawEnabled&&guestActiveTab==='draw')switchGuestTab('main');
}
function ensureBackgroundImageLoaded(){
  if(!backgroundImageSrc){backgroundImageEl=null;return null;}
  if(backgroundImageEl&&backgroundImageEl.src===backgroundImageSrc)return backgroundImageEl;
  const img=new Image();
  img.onload=()=>drawAll();
  img.src=backgroundImageSrc;
  backgroundImageEl=img;
  return img;
}
function setBackgroundImage(src){
  backgroundImageSrc=src||'';
  ensureBackgroundImageLoaded();
  drawAll();
  if(isHost)syncToServer();
}
function clampChargeGain(v){
  const n=parseInt(v);
  if(isNaN(n))return 0;
  return Math.max(0,Math.min(MAX_CHARGES,n));
}
function ensureParticipantChargeFields(p){
  if(!p)return p;
  p.maxCharges=MAX_CHARGES;
  p.charges=clampChargeValue(p.charges);
  p.chargesTurnStartAdd=clampChargeGain(p.chargesTurnStartAdd);
  p.chargesTurnEndAdd=clampChargeGain(p.chargesTurnEndAdd);
  if(p.emoteKey===undefined)p.emoteKey=null;
  if(p.emoteUntil===undefined)p.emoteUntil=null;
  return p;
}
function getEmoteByKey(key){
  return EMOTE_DATA.find(e=>e.key===key)||ENEMY_EMOTE_DATA.find(e=>e.key===key)||null;
}
function getEmoteImage(key){
  const meta=getEmoteByKey(key);
  if(!meta)return null;
  if(!emoteImgCache.has(key)){
    const img=new Image();
    img.onload=()=>{
      drawAll();
      if(emoteMenuActive)drawEmoteMenu();
      if(enemyEmoteMenuActive)drawEnemyEmoteMenu();
    };
    img.src=meta.src;
    emoteImgCache.set(key,img);
  }
  return emoteImgCache.get(key);
}
function getEmoteOverlayLayer(){
  if(emoteOverlayLayer&&emoteOverlayLayer.isConnected)return emoteOverlayLayer;
  const container=document.getElementById('canvas-container');
  if(!container)return null;
  const layer=document.createElement('div');
  layer.id='emote-overlay-layer';
  layer.style.position='absolute';
  layer.style.left='0';
  layer.style.top='0';
  layer.style.width='100%';
  layer.style.height='100%';
  layer.style.pointerEvents='none';
  layer.style.zIndex='8';
  container.appendChild(layer);
  emoteOverlayLayer=layer;
  return layer;
}
function removeEmoteOverlayNode(participantId){
  const node=emoteOverlayNodes.get(participantId);
  if(!node)return;
  node.remove();
  emoteOverlayNodes.delete(participantId);
}
function syncAnimatedEmoteOverlay(participant,px,py,pr,meta){
  const layer=getEmoteOverlayLayer();
  if(!layer||!participant||!meta?.src)return false;
  let node=emoteOverlayNodes.get(participant.id);
  if(!node){
    node=document.createElement('img');
    node.alt='';
    node.style.position='absolute';
    node.style.pointerEvents='none';
    node.style.objectFit='cover';
    node.style.zIndex='8';
    emoteOverlayNodes.set(participant.id,node);
    layer.appendChild(node);
  }
  if(node.dataset.src!==meta.src){
    node.src=meta.src;
    node.dataset.src=meta.src;
  }
  const rect=canvas.getBoundingClientRect();
  if(!rect.width||!rect.height)return false;
  const emoteScale=meta.scale||1;
  const dw=pr*2.08*emoteScale,dh=pr*2.08*emoteScale;
  const sx=(px/canvas.width)*rect.width;
  const sy=(py/canvas.height)*rect.height;
  const sw=(dw/canvas.width)*rect.width;
  const sh=(dh/canvas.height)*rect.height;
  node.style.left=`${sx-sw/2}px`;
  node.style.top=`${sy-sh/2}px`;
  node.style.width=`${sw}px`;
  node.style.height=`${sh}px`;
  return true;
}
function cleanupAnimatedEmoteOverlays(activeIds){
  for(const [participantId] of emoteOverlayNodes){
    if(!activeIds.has(participantId))removeEmoteOverlayNode(participantId);
  }
}
function isEmoteActive(p,nowMs=Date.now()){
  if(!p||!p.emoteKey)return false;
  if(p.emoteUntil==null)return true;
  if(p.emoteUntil<=nowMs){
    p.emoteKey=null;
    p.emoteUntil=null;
    return false;
  }
  return true;
}
function isEmoteAnimated(key){
  return !!getEmoteByKey(key)?.animated;
}
function applyParticipantEmote(p,emoteKey,durationMs,notifyServer=true){
  if(!p)return false;
  const meta=getEmoteByKey(emoteKey);
  if(!meta)return false;
  const loopsUntilInterrupt=!!meta.animated;
  p.emoteKey=meta.key;
  p.emoteUntil=loopsUntilInterrupt?null:(Date.now()+Math.max(250,Math.min(10000,parseInt(durationMs,10)||meta.durationMs)));
  startAnimLoop();
  drawAll();
  if(notifyServer){
    if(isHost)syncToServer();
    else send({type:'guest_emote_set',participantId:p.id,emoteKey:p.emoteKey,durationMs:meta.durationMs,loop:loopsUntilInterrupt});
  }
  return true;
}
function clearParticipantEmote(p,notifyServer=true){
  if(!p||(!p.emoteKey&&!p.emoteUntil))return false;
  p.emoteKey=null;
  p.emoteUntil=null;
  drawAll();
  if(notifyServer){
    if(isHost)syncToServer();
    else send({type:'guest_emote_clear',participantId:p.id});
  }
  return true;
}
function emoteTargetAtScreen(screenPos){
  const rect=canvas.getBoundingClientRect();
  const cx=screenPos.x-rect.left,cy=screenPos.y-rect.top;
  if(cx<0||cy<0||cx>canvas.width||cy>canvas.height)return null;
  return findParticipantAt({x:cx,y:cy});
}
function getEmoteTargetParticipant(){
  if(isHost){
    if(activeParticipant)return activeParticipant;
    return emoteTargetAtScreen(emoteMenuOrigin);
  }
  return participants.find(p=>p.id===localSelection)||null;
}
function announceCharge(text){
  if(!text)return;
  showAlert(`📣 ${text}`);
  send({type:'charge_announce',text});
}
function setGuestChargeStatus(msg,type='info'){
  if(!guestChargeStatusEl)return;
  guestChargeStatusEl.textContent=msg;
  if(type==='warn')guestChargeStatusEl.style.color='var(--accent2)';
  else if(type==='error')guestChargeStatusEl.style.color='var(--danger)';
  else if(type==='ok')guestChargeStatusEl.style.color='var(--success)';
  else guestChargeStatusEl.style.color='var(--text-muted)';
  setTimeout(()=>{guestChargeStatusEl.textContent='';},4500);
}
function applyParticipantCharge(p,nextValue,reason,announce=true){
  if(!p)return false;
  ensureParticipantChargeFields(p);
  const before=p.charges;
  p.charges=clampChargeValue(nextValue);
  if(before===p.charges)return false;
  if(announce){
    const why=reason?` (${reason})`:'';
    announceCharge(`${p.name}: charges ${before} → ${p.charges}${why}`);
  }
  return true;
}
function applyTurnChargeGain(p,phase){
  if(!p)return false;
  ensureParticipantChargeFields(p);
  const add=phase==='start'?p.chargesTurnStartAdd:p.chargesTurnEndAdd;
  if(add<=0)return false;
  const label=phase==='start'?`turn start +${add}`:`turn end +${add}`;
  return applyParticipantCharge(p,(p.charges||0)+add,label,true);
}
function refreshGuestChargeControls(){
  if(isHost)return;
  if(!guestChargeStartGainEl||!guestChargeEndGainEl)return;
  const p=participants.find(pp=>pp.id===localSelection);
  const canEdit=!!p&&p.type==='player';
  const isMyTurn=!!canEdit&&participants[turnIndex]?.id===p.id;
  if(guestChargesDecreaseBtn)guestChargesDecreaseBtn.disabled=!canEdit;
  if(guestChargesIncreaseBtn)guestChargesIncreaseBtn.disabled=!canEdit;
  if(guestApplyChargeGainsBtn)guestApplyChargeGainsBtn.disabled=!canEdit;
  if(guestEndTurnBtn){
    guestEndTurnBtn.disabled=!isMyTurn;
    guestEndTurnBtn.textContent=isMyTurn?'⏭ End My Turn':'⏭ End My Turn (wait)';
  }
  if(canEdit){
    ensureParticipantChargeFields(p);
    if(document.activeElement!==guestChargeStartGainEl)guestChargeStartGainEl.value=String(p.chargesTurnStartAdd||0);
    if(document.activeElement!==guestChargeEndGainEl)guestChargeEndGainEl.value=String(p.chargesTurnEndAdd||0);
  }else{
    if(document.activeElement!==guestChargeStartGainEl)guestChargeStartGainEl.value='';
    if(document.activeElement!==guestChargeEndGainEl)guestChargeEndGainEl.value='';
  }
}
let _confirmCb=null;
function showConfirm(msg,onOk,onCancel){
  document.getElementById('uiConfirmMsg').textContent=msg;
  document.getElementById('uiConfirmModal').style.display='flex';
  _confirmCb={ok:onOk,cancel:onCancel};
}
let _promptCb=null;
function showPrompt(label,def,onOk){
  document.getElementById('uiPromptLabel').textContent=label;
  const inp=document.getElementById('uiPromptInput');
  inp.value=def||'';
  document.getElementById('uiPromptModal').style.display='flex';
  setTimeout(()=>inp.focus(),50);
  _promptCb=onOk;
}
document.getElementById('uiConfirmOk').addEventListener('click',()=>{
  document.getElementById('uiConfirmModal').style.display='none';
  const cb=_confirmCb;
  _confirmCb=null;
  if(cb?.ok)cb.ok();
});
document.getElementById('uiConfirmCancel').addEventListener('click',()=>{
  document.getElementById('uiConfirmModal').style.display='none';
  const cb=_confirmCb;
  _confirmCb=null;
  if(cb?.cancel)cb.cancel();
});
document.getElementById('uiPromptOk').addEventListener('click',()=>{
  const val=document.getElementById('uiPromptInput').value;
  document.getElementById('uiPromptModal').style.display='none';
  const cb=_promptCb;
  _promptCb=null;
  if(cb)cb(val);
});
document.getElementById('uiPromptCancel').addEventListener('click',()=>{
  document.getElementById('uiPromptModal').style.display='none';
  _promptCb=null;
});
document.getElementById('uiPromptInput').addEventListener('keydown',e=>{
  if(e.key==='Enter'){document.getElementById('uiPromptOk').click();}
  if(e.key==='Escape'){document.getElementById('uiPromptCancel').click();}
});

/* ================================================================
   INIT UI
================================================================ */
function initUI() {
  if (isHost) {
    document.body.classList.add('host-mode');
    document.body.classList.remove('guest-mode');
    document.getElementById('hostControls').style.display='block';
    const enemyEmBtn=document.getElementById('enemyEmoteSettingsBtn');
    if(enemyEmBtn)enemyEmBtn.style.display='';
    roleBadge.textContent='DM'; roleBadge.className='role-badge host';
    document.getElementById('rs-combat-flow').classList.add('host-show');
    document.getElementById('guestInitToggleWrap').style.display='flex';
    document.getElementById('rs-toggle-btn').classList.add('host-visible');
    // Sort order toggle
    const sortBtn=document.getElementById('rs-sort-btn');
    sortBtn.style.display='inline-block';
    sortBtn.addEventListener('click',()=>{
      initiativeDisplayOrder=initiativeDisplayOrder==='initiative'?'alpha':'initiative';
      sortBtn.textContent=initiativeDisplayOrder==='alpha'?'Init':'A–Z';
      sortBtn.classList.toggle('alpha-active',initiativeDisplayOrder==='alpha');
      document.getElementById('sortOrderLabel').textContent=initiativeDisplayOrder==='alpha'?'Alphabetical':'Initiative order';
      updateInitiativeList();syncToServer();
    });
    // Host can collapse/expand right sidebar
    document.getElementById('rs-toggle-btn').addEventListener('click', ()=>{
      const rs=document.getElementById('right-sidebar');
      rs.classList.toggle('collapsed');
      document.getElementById('rs-toggle-btn').textContent=rs.classList.contains('collapsed')?'›':'‹';
    });
    document.getElementById('rs-collapsed-label').style.cursor='pointer';
    document.getElementById('rs-collapsed-label').addEventListener('click', ()=>{
      document.getElementById('right-sidebar').classList.remove('collapsed');
      document.getElementById('rs-toggle-btn').textContent='‹';
    });
  } else {
    document.body.classList.add('guest-mode');
    document.body.classList.remove('host-mode');
    document.getElementById('guestControls').style.display='flex';
    document.getElementById('guestDiceRequestPanel')?.style && (document.getElementById('guestDiceRequestPanel').style.display='flex');
    roleBadge.textContent=GUEST_NAME; roleBadge.className='role-badge guest';
    switchGuestTab('main');
    refreshGuestDrawAccess();
    loadLocalNicknamesUI();
    updateGuestDicePanel();
    // Guests always see the initiative sidebar — no collapsing
    document.getElementById('right-sidebar').classList.remove('collapsed');
  }
  // Item viewer modal close
  document.getElementById('itemViewerClose').addEventListener('click', closeItemViewer);
  document.getElementById('itemViewerModal').addEventListener('click', e=>{ if(e.target===document.getElementById('itemViewerModal'))closeItemViewer(); });
  initInventoryUI();
}
initUI();

function applyGuestInitiativeVisibility(){
  if(isHost)return;
  document.body.classList.toggle('guest-init-hidden', !guestInitiativeEnabled);
  if(guestInitiativeEnabled)document.getElementById('right-sidebar').classList.remove('collapsed');
}

// Flush deferred initiative list rebuilds when focus leaves an editing field
if(isHost){
  document.getElementById('initiativeOrderRight').addEventListener('focusout',()=>{
    // Small delay so blur fires before any click handler on the same element
    setTimeout(()=>{
      const el=document.activeElement;
      const inList=document.getElementById('initiativeOrderRight').contains(el);
      const editing=inList&&(el.tagName==='INPUT'||el.tagName==='TEXTAREA');
      if(!editing&&pendingInitiativeUpdate){pendingInitiativeUpdate=false;updateInitiativeList();}
    },50);
  });
}

/* ================================================================
   WEBSOCKET
================================================================ */
function connect() {
  try { ws=new WebSocket(WS_URL); } catch { setConnStatus('error','WS error'); return; }
  setConnStatus('connecting','Connecting…');
  ws.addEventListener('open', ()=>{ setConnStatus('connected','Connected'); send({type:'hello',mode:MODE,name:isHost?'DM':GUEST_NAME,room:ROOM_CODE}); });
  ws.addEventListener('message', ev=>{ try{handleMessage(JSON.parse(ev.data));}catch(e){console.error(e);} });
  ws.addEventListener('close', ()=>{ setConnStatus('error','Disconnected — reconnecting…'); setTimeout(connect,3000); });
  ws.addEventListener('error', ()=>setConnStatus('error','WS error'));
}
function send(obj){
  if(ws&&ws.readyState===WebSocket.OPEN){
    if(obj?.type==='approve_request'||obj?.type==='dice_request_status'||obj?.type==='dice_request'){
      console.info('[combat] send',obj.type,{requestId:obj.requestId||obj.id||null,approved:obj.approved});
    }
    ws.send(JSON.stringify(obj));
  }else if(obj?.type==='approve_request'||obj?.type==='dice_request_status'||obj?.type==='dice_request'){
    console.warn('[combat] send dropped (ws not open)',obj.type,{requestId:obj.requestId||obj.id||null,state:ws?.readyState});
  }
}
window.__broadcastAppMessage=(obj)=>send(obj);
window.__isHost=!!isHost;
function setConnStatus(s,t){ connLabel.textContent=t; connDot.className='conn-dot'+(s==='connected'?' connected':s==='error'?' error':''); }
if (!isHost) setInterval(()=>send({type:'state_request'}),5000);

function makeDiceRequestId(){
  const base=`${Date.now().toString(36)}-${(++diceRequestCounter).toString(36)}`;
  return crypto?.randomUUID?.() || `dice-${base}`;
}

function hashStringToSeed(str=''){
  let h=2166136261>>>0;
  for(let i=0;i<str.length;i++){
    h^=str.charCodeAt(i);
    h=Math.imul(h,16777619);
  }
  return h>>>0;
}

function normalizeRequestId(req={}){
  const id=req.id||req.requestId||makeDiceRequestId();
  return {id,requestId:id};
}

function getCurrentSharedDiceState(){
  return window.combatDice?.getSharedState?.() || null;
}


function relayPromptRollResult(payload){
  // Guests should not publish their own roll result.
  // The host is authoritative.
  return;
}

function requestDiceRollLegacy(expr, opts = {}) {
  const normalized = (expr || '1d20').trim() || '1d20';

  // HOST rolls directly
  if (isHost) {
    window.rollCombatDice?.(normalized, {
      thrower: 'DM'
    });
    return;
  }

  // Prevent duplicate pending requests
  if (activeDiceRequestId) {
    return;
  }

  const reqId=makeDiceRequestId();
  const req = {
    id: reqId,
    requestId: reqId,
    requestType: 'dice',
    kind: 'dice',
    expression: normalized,
    fromGuestName: GUEST_NAME,
    guestName: GUEST_NAME,
    createdAt: Date.now(),
    prompted: !!opts.prompted,
    promptId: opts.promptId || null,
    autoApprove: false
  };

  activeDiceRequestId = req.id;

  window.__broadcastAppMessage?.({
    type: 'dice_request',
    request: req
  });

  const s = document.getElementById('diceResult');

  if (s) {
    s.className = '';
    s.textContent = '⏳ Waiting for DM approval...';
  }
}

function finishGuestDiceRoll(msg) {
  const s = document.getElementById('diceResult');
  if (s) {
    s.className = '';
    const total = msg.total ?? msg.result ?? '';
    s.textContent = `🎲 Result: ${total}`;
  }
  activeDiceRequestId = null;
}

function rollPromptedDice(expr, promptId){
  requestDiceRoll(expr, { prompted: true, promptId });
}

function showDicePrompt(expr, promptId){
  if(isHost) return;
  const normalized=String(expr||'1d20').trim()||'1d20';
  if(promptId && lastDicePrompt===promptId) return;
  if(promptId) lastDicePrompt=promptId;
  const toast=document.createElement('div');toast.className='reminder-toast';
  toast.innerHTML=`
    <div class="toast-header"><div class="toast-dot" style="background:#6366f1"></div><span>🎲 DM wants you to roll!</span></div>
    <div class="toast-body">Roll <strong>${escHtml(normalized)}</strong> — click below when ready.</div>
    <button class="toast-roll-btn">🎲 Roll ${escHtml(normalized)}</button>
    <button class="toast-dismiss">✕</button>
  `;
  const timer=setTimeout(()=>dismissToast(toast),30000);
  toast.dataset.timer=String(timer);
  toast.querySelector('.toast-dismiss').addEventListener('click',e=>{e.stopPropagation();dismissToast(toast);});
  toast.querySelector('.toast-roll-btn').addEventListener('click',()=>{dismissToast(toast);rollPromptedDice(normalized, promptId);});
  toastContainer().appendChild(toast);
}

function applyIncomingDiceState(diceState){
  if(!diceState) return;
  if(diceState.prompt){
    showDicePrompt(diceState.prompt.expression||diceState.expression||'1d20', diceState.prompt.id||diceState.prompt.promptId);
  }
  if(diceState.cleared){
    window.clearCombatDice?.();
    return;
  }
  const localState=getCurrentSharedDiceState();
  const localRollId=localState?.rollId||null;
  const incomingRollId=diceState.rollId||null;
  if(diceState.rolling){
    if(incomingRollId && incomingRollId!==localRollId){
      window.startSharedDiceRoll?.(diceState) || window.combatDice?.startSharedRoll?.(diceState);
    }
    window.applySharedDiceState?.(diceState);
    return;
  }
  if((diceState.results&&diceState.results.length)||Number.isFinite(diceState.total)){
    if(incomingRollId && incomingRollId!==localRollId){
      window.applySharedDiceResult?.(diceState) || window.combatDice?.applySharedResult?.(diceState);
    }
    if(diceState.diceState) window.applySharedDiceState?.(diceState.diceState);
  }
}

function makeSharedRollPayload(req){
  const normalizeVec3=(v)=>{
    if(!v||typeof v!=='object')return null;
    const x=Number(v.x),y=Number(v.y),z=Number(v.z);
    if(!Number.isFinite(x)||!Number.isFinite(y)||!Number.isFinite(z))return null;
    return {x,y,z};
  };
  const normalizeQuat=(q)=>{
    if(!q||typeof q!=='object')return null;
    const x=Number(q.x),y=Number(q.y),z=Number(q.z),w=Number(q.w);
    if(!Number.isFinite(x)||!Number.isFinite(y)||!Number.isFinite(z)||!Number.isFinite(w))return null;
    return {x,y,z,w};
  };

  const expression=String(req.expression||'1d20').trim()||'1d20';
  const reqId=req.requestId||req.id||makeDiceRequestId();
  const rollId=req.rollId||makeDiceRequestId();
  const seed=req.seed!==undefined ? (req.seed>>>0) : hashStringToSeed(`${rollId}|${expression}|${req.fromGuestName||req.guestName||'guest'}`);
  const throwDataRaw=req.throwData&&typeof req.throwData==='object'?req.throwData:null;
  const throwData=throwDataRaw?{
    dieIndex:Number.isInteger(throwDataRaw.dieIndex)?Math.max(0,throwDataRaw.dieIndex):0,
    sides:Number.isFinite(Number(throwDataRaw.sides))?Number(throwDataRaw.sides):undefined,
    sign:Number(throwDataRaw.sign)<0?-1:1,
    position:normalizeVec3(throwDataRaw.position),
    quaternion:normalizeQuat(throwDataRaw.quaternion),
    velocity:normalizeVec3(throwDataRaw.velocity),
    angularVelocity:normalizeVec3(throwDataRaw.angularVelocity),
  }:null;

  return {
    rollId,
    requestId:reqId,
    expression,
    seed,
    throwData,
    fromGuestName:req.fromGuestName||req.guestName||'Guest',
    requestType:'dice',
    approved:true,
  };
}

function approvePendingRequest(req, approve) {
  const reqId=req?.id||req?.requestId;
  const kind = req.requestType || req.kind || req.type || 'move';
  console.info('[combat] approvePendingRequest',{
    kind,
    approve,
    reqId,
    req
  });

  // -----------------------------
  // HOST-AUTHORITATIVE DICE FLOW
  // -----------------------------
  if (kind === 'dice') {
    // Keep pending list server-authoritative. Do not remove locally here,
    // otherwise failed/missed status messages cause "ghost" re-appears later.
    if(!reqId)return;
    if (!approve) {
      send({
        type: 'dice_request_status',
        requestId: reqId,
        id: reqId,
        approved: false,
        reason: 'denied'
      });
      return;
    }

    try{
      const payload = makeSharedRollPayload(req);
      activeDiceRequestId = payload.requestId;

      // If host dice are still marked as rolling, reset first so this approval
      // cannot silently no-op due to the roller's early-return guard.
      if (window.combatDice?._rolling) {
        window.clearCombatDice?.();
      }

      send({
        type: 'dice_request_status',
        requestId: reqId,
        id: reqId,
        approved: true,
        rollId: payload.rollId
      });

      // Host performs the authoritative roll.
      window.rollCombatDice?.(
        payload.expression || req.expression || '1d20',
        {
          thrower:
            payload.fromGuestName ||
            req.fromGuestName ||
            req.guestName ||
            'Guest',
          requestId: payload.requestId,
          rollId: payload.rollId,
          seed: payload.seed,
          throwData: payload.throwData,
          shared: true
        }
      );

      const s = document.getElementById('diceResult');
      if (s) {
        s.className = '';
        s.textContent = '🎲 Rolling...';
      }
    }catch(err){
      console.error('[combat] approve dice failed',{
        reqId,
        req,
        error:err?.message||err
      });
      send({
        type:'dice_request_status',
        requestId:reqId,
        id:reqId,
        approved:false,
        reason:'host_error'
      });
    }

    return;
  }

  // -----------------------------
  // NORMAL MOVE REQUESTS
  // -----------------------------
  send({
    type: 'approve_request',
    requestId: reqId,
    id: reqId,
    approve
  });
}


/* ================================================================
   MESSAGES
================================================================ */
function handleMessage(msg) {
  if (msg.type==='host_ack'&&isHost){applyHostState(msg.state);updatePendingList(msg.pendingRequests||[]);drawAll();return;}
  if (msg.type==='state_echo'&&isHost){applyHostState(msg.state);drawAll();return;}
  if (msg.type==='guest_state'&&!isHost){applyGuestState(msg.state);return;}
  if (msg.type==='map_ping'){
    if(!rememberPingId(msg.pingId))return;
    addPingEffect(msg.x,msg.y,msg.pingIndex,msg.label,msg.fromName);
    return;
  }
  if (msg.type==='guest_ping'&&isHost){
    const p=participants.find(pp=>pp.id===msg.participantId);
    if(!p)return;
    p.pingUntil=Date.now()+3000;
    startAnimLoop();
    updateInitiativeList();
    drawAll();
    syncToServer();
    return;
  }
  if(msg.type==='guest_emote_result'&&!isHost){
    if(msg.ok!==true)showAlert('❌ Emote rejected by DM.');
    return;
  }
  if (msg.type==='dice_request'&&isHost){
    const rawReq={...(msg.request||msg)};
    const ids=normalizeRequestId(rawReq);
    const req={...rawReq,...ids,requestType:'dice',kind:'dice'};
    console.info('[combat] host received dice_request',{
      requestId:req.id,
      from:req.fromGuestName||req.guestName||'Guest',
      expression:req.expression||'1d20'
    });
    pendingRequests=[...pendingRequests.filter(r=>r.id!==req.id),req];
    updatePendingList(pendingRequests);
    if(req.prompted || req.autoApprove || guestDiceEnabled || guestDiceThrowEnabled){
      approvePendingRequest(req,true);
    }
    return;
  }
  if (msg.type==='dice_request_status'&&!isHost){
    const s=document.getElementById('diceResult');
    const statusRequestId=msg.requestId||msg.id||null;
    const matchesActive=!statusRequestId||!activeDiceRequestId||statusRequestId===activeDiceRequestId;
    console.info('[combat] guest received dice_request_status',{
      statusRequestId,
      activeDiceRequestId,
      matchesActive,
      approved:msg.approved,
      rollId:msg.rollId||null
    });
    if(msg.approved===true){
      if(matchesActive&&s){s.className='rolling';s.textContent='🎲 Approved — rolling…';}
      const g=document.getElementById('guestDiceStatus');
      if(matchesActive&&g){g.textContent='🎲 Approved — rolling…';g.style.color='var(--accent2)';}
    }else if(msg.approved===false){
      if(matchesActive&&s){s.className='';s.textContent='❌ Dice request denied.';}
      const g=document.getElementById('guestDiceStatus');
      if(matchesActive&&g){g.textContent='❌ Dice request denied.';g.style.color='var(--danger)';}
      if(matchesActive)activeDiceRequestId=null;
    }
    return;
  }
  if (msg.type==='dice_roll_start'){
    if(isHost&&msg.source==='host')return;
    combatDice.startSharedRoll(msg);
    return;
  }
  if (msg.type==='dice_roll_state'){
    if(isHost&&msg.source==='host')return;
    window.applySharedDiceState?.(msg.state||msg);
    return;
  }
if (msg.type === 'dice_roll_result') {
  combatDice.applySharedResult(msg);

  const s = document.getElementById('diceResult');

  if (s) {
    s.className = '';

    const total = msg.total ?? msg.result ?? '';

    s.textContent = `🎲 Result: ${total}`;
  }

  // Request is now finished
  activeDiceRequestId = null;

  if (msg.diceState) {
    window.applySharedDiceState?.(msg.diceState);
  }

  return;
}
  if (msg.type==='dice_clear'){
    if(isHost&&msg.source==='host')return;
    combatDice.clearDice();
    return;
  }
  if (msg.type==='pending_requests_update'&&isHost){updatePendingList(msg.requests||[]);return;}
  if (msg.type==='guest_connected'&&isHost){
    if(!connectedGuests.includes(msg.name))connectedGuests.push(msg.name);
    guestListEl.textContent=connectedGuests.join(', ')||'None yet.';renderAssignmentList();return;
  }
  if (msg.type==='guest_disconnected'&&isHost){
    connectedGuests=connectedGuests.filter(n=>n!==msg.name);
    guestListEl.textContent=connectedGuests.join(', ')||'None yet.';renderAssignmentList();return;
  }
  if (msg.type==='request_result'&&!isHost){
    const s=guestMoveStatus;
    if(msg.ok===true){s.textContent='✅ Move approved!';s.style.color='var(--success)';}
    else if(msg.ok===false){const r={not_your_token:"That's not your token.",not_your_turn:"It's not your turn.",participant_not_found:"Token not found."};s.textContent='❌ '+(r[msg.reason]||'Move rejected.');s.style.color='var(--danger)';}
    else if(msg.queued){s.textContent='⏳ Waiting for DM approval…';s.style.color='var(--accent2)';}
    setTimeout(()=>{s.textContent='';},5000);return;
  }
  if (msg.type==='request_resolved'&&!isHost){
    if(msg.approved){guestMoveStatus.textContent='✅ DM approved your move!';guestMoveStatus.style.color='var(--success)';lastTargetPos=null;updateGuestTargetInfo();}
    else{guestMoveStatus.textContent='❌ DM denied your move.';guestMoveStatus.style.color='var(--danger)';}
    setTimeout(()=>{guestMoveStatus.textContent='';},5000);drawAll();return;
  }
  if(msg.type==='charge_announce'){
    if(msg.text)showAlert(`📣 ${msg.text}`);
    return;
  }
  if(msg.type==='guest_charge_update_result'&&!isHost){
    if(msg.ok===true&&msg.mode==='config')setGuestChargeStatus('✅ Charge gain settings updated.','ok');
    else if(msg.ok===true)setGuestChargeStatus('✅ Charges updated.','ok');
    else setGuestChargeStatus('❌ Charge update rejected.','error');
    refreshGuestChargeControls();
    return;
  }
  if(msg.type==='guest_end_turn_result'&&!isHost){
    if(msg.ok===true){
      guestMoveStatus.textContent='⏭ End turn request sent.';
      guestMoveStatus.style.color='var(--accent2)';
    }else{
      const r={not_your_token:"That's not your token.",not_your_turn:"It's not your turn.",participant_not_found:'Token not found.'};
      guestMoveStatus.textContent='❌ '+(r[msg.reason]||'Could not end turn.');
      guestMoveStatus.style.color='var(--danger)';
    }
    setTimeout(()=>{guestMoveStatus.textContent='';},4000);
    refreshGuestChargeControls();
    return;
  }
  if(msg.type==='guest_end_turn_request'&&isHost){
    const requestedId=msg.participantId;
    if(!participants.length)return;
    const current=participants[turnIndex];
    if(!current||current.id!==requestedId)return;
    nextBtn.click();
    if(msg.fromGuestName)showAlert(`⏭ ${msg.fromGuestName} ended their turn.`);
    return;
  }
  if(msg.type==='guest_bag_item_move_result'&&!isHost){
    if(msg.ok!==true)showAlert('❌ Item move rejected.');
    return;
  }
  if (msg.type==='host_disconnected'&&!isHost){setConnStatus('error','DM disconnected');currentTurnBanner.style.display='none';return;}
  if (msg.type==='draw_rejected'&&!isHost){guestMoveStatus.textContent='❌ Drawing disabled by DM.';guestMoveStatus.style.color='var(--danger)';setTimeout(()=>{guestMoveStatus.textContent='';},3000);return;}
  if (msg.type==='dice_roll_prompt'){
    if(!isHost) showDicePrompt(msg.expression||msg.prompt?.expression||'1d20', msg.id||msg.promptId||msg.prompt?.id);
    return;
  }
}

/* ================================================================
   STATE APPLICATION
================================================================ */
renderPortraitPreview(newPortraitPreview, pendingNewPortrait);
renderPortraitPreview(editPortraitPreview, '');

function applyParticipantsWithMotion(nextParticipants){
  const previousById=new Map((participants||[]).map(p=>[p.id,p]));
  participants=(nextParticipants||[]).map(ensureParticipantChargeFields);
  const seen=new Set();
  for(const p of participants){
    seen.add(p.id);
    const prev=previousById.get(p.id);
    if(prev && (prev.x!==p.x || prev.y!==p.y)){
      animateParticipantMove(p.id,prev.x,prev.y,p.x,p.y,1000);
    }
  }
  for(const id of [...movementAnimations.keys()]){
    if(!seen.has(id))movementAnimations.delete(id);
  }
}
function applyHostState(state) {
  if(!state)return;
  if(state.participants!==undefined)applyParticipantsWithMotion(state.participants);
  if(state.objects!==undefined)objects=deserializeObjects(state.objects);
  if(state.turnIndex!==undefined)turnIndex=state.turnIndex;
  if(state.pixelsPerUnit!==undefined){pixelsPerUnit=state.pixelsPerUnit;cfgPixelsPerUnit.value=pixelsPerUnit;}
  if(state.canvasWidth&&state.canvasHeight){canvas.width=state.canvasWidth;canvas.height=state.canvasHeight;battleWidthEl.value=state.canvasWidth;battleHeightEl.value=state.canvasHeight;}
  if(state.moveToleranceUnits!==undefined)cfgTolerance.value=state.moveToleranceUnits;
  if(state.autoApproveIfWithinTolerance!==undefined)cfgAutoApprove.checked=state.autoApproveIfWithinTolerance;
  if(state.backgroundImageSrc!==undefined){
    backgroundImageSrc=state.backgroundImageSrc||'';
    ensureBackgroundImageLoaded();
  }
  if(state.backgroundFillMode!==undefined){
    backgroundFillMode=state.backgroundFillMode||'stretch';
    if(backgroundFillModeEl)backgroundFillModeEl.value=backgroundFillMode;
  }
  if(state.guestDrawEnabled!==undefined){guestDrawEnabled=state.guestDrawEnabled;guestDrawToggle.checked=guestDrawEnabled;}
  if(state.guestDiceEnabled!==undefined){guestDiceEnabled=state.guestDiceEnabled;if(guestDiceToggle)guestDiceToggle.checked=guestDiceEnabled;}
  if(state.guestDiceThrowEnabled!==undefined){guestDiceThrowEnabled=state.guestDiceThrowEnabled;if(guestDiceThrowToggle)guestDiceThrowToggle.checked=guestDiceThrowEnabled;}
  if(state.guestInitiativeEnabled!==undefined){guestInitiativeEnabled=state.guestInitiativeEnabled;if(guestInitiativeToggle)guestInitiativeToggle.checked=guestInitiativeEnabled;}
  if(state.initiativeDisplayOrder!==undefined){
    initiativeDisplayOrder=state.initiativeDisplayOrder;
    const sortBtn=document.getElementById('rs-sort-btn');
    if(sortBtn){
      sortBtn.textContent=initiativeDisplayOrder==='alpha'?'Init':'A–Z';
      sortBtn.classList.toggle('alpha-active',initiativeDisplayOrder==='alpha');
    }
    const lbl=document.getElementById('sortOrderLabel');
    if(lbl)lbl.textContent=initiativeDisplayOrder==='alpha'?'Alphabetical':'Initiative order';
  }
  if(state.diceSettings!==undefined){
    window.combatDice?.applySettings?.(state.diceSettings);
    if(diceRandomizeColorEl&&state.diceSettings.randomizeColors!==undefined)diceRandomizeColorEl.checked=!!state.diceSettings.randomizeColors;
    if(diceColorEl&&state.diceSettings.diceColor!==undefined)diceColorEl.value=state.diceSettings.diceColor;
    if(diceSizeEl&&state.diceSettings.dieScale!==undefined)diceSizeEl.value=state.diceSettings.dieScale;
    if(diceVelocityEl&&state.diceSettings.launchVelocity!==undefined)diceVelocityEl.value=state.diceSettings.launchVelocity;
    if(diceSpinEl&&state.diceSettings.launchSpin!==undefined)diceSpinEl.value=state.diceSettings.launchSpin;
    if(diceBounceEl&&state.diceSettings.bounciness!==undefined)diceBounceEl.value=state.diceSettings.bounciness;
    updateDiceUiLabels();
  }
  if(state.bagItems!==undefined)bagItems=normalizeBagItems(state.bagItems);
  if(state.bagWeightMultipliers!==undefined)bagWeightMultipliers=normalizeBagWeightMultipliers(state.bagWeightMultipliers);
  if(state.customEmotes&&Array.isArray(state.customEmotes)&&state.customEmotes.length===8){
    applyEmoteConfig(state.customEmotes.map(e=>({...e})));
  }
  if(state.customEnemyEmotes&&Array.isArray(state.customEnemyEmotes)&&state.customEnemyEmotes.length===8){
    applyEnemyEmoteConfig(state.customEnemyEmotes.map(e=>({...e})));
  }
  if(!isHost && state.latestDicePrompt) showDicePrompt(state.latestDicePrompt.expression||state.latestDicePrompt.expr||'1d20', state.latestDicePrompt.id||state.latestDicePrompt.promptId);
  if(state.diceState) applyIncomingDiceState(state.diceState);
  if(activeParticipant)activeParticipant=participants.find(p=>p.id===activeParticipant.id)||null;
  checkAndStartAnimLoop();updateInitiativeList();renderAssignmentList();renderInventory();
}

function applyGuestState(state) {
  if(!state)return;
  applyParticipantsWithMotion(state.participants||[]);
  objects=deserializeObjects(state.objects||[]);
  turnIndex=state.turnIndex||0;
  if(state.pixelsPerUnit)pixelsPerUnit=state.pixelsPerUnit;
  if(state.canvasWidth&&state.canvasHeight){canvas.width=state.canvasWidth;canvas.height=state.canvasHeight;}
  if(state.backgroundImageSrc!==undefined){
    backgroundImageSrc=state.backgroundImageSrc||'';
    ensureBackgroundImageLoaded();
  }
  if(state.backgroundFillMode!==undefined){
    backgroundFillMode=state.backgroundFillMode||'stretch';
    if(backgroundFillModeEl)backgroundFillModeEl.value=backgroundFillMode;
  }
  if(state.diceSettings!==undefined){
    window.combatDice?.applySettings?.(state.diceSettings);
    if(diceRandomizeColorEl&&state.diceSettings.randomizeColors!==undefined)diceRandomizeColorEl.checked=!!state.diceSettings.randomizeColors;
    if(diceColorEl&&state.diceSettings.diceColor!==undefined)diceColorEl.value=state.diceSettings.diceColor;
    if(diceSizeEl&&state.diceSettings.dieScale!==undefined)diceSizeEl.value=state.diceSettings.dieScale;
    if(diceVelocityEl&&state.diceSettings.launchVelocity!==undefined)diceVelocityEl.value=state.diceSettings.launchVelocity;
    if(diceSpinEl&&state.diceSettings.launchSpin!==undefined)diceSpinEl.value=state.diceSettings.launchSpin;
    if(diceBounceEl&&state.diceSettings.bounciness!==undefined)diceBounceEl.value=state.diceSettings.bounciness;
    updateDiceUiLabels();
  }
  if(state.guestDrawEnabled!==undefined){
    guestDrawEnabled=state.guestDrawEnabled;
    refreshGuestDrawAccess();
    if(!guestDrawEnabled){guestIsDrawing=false;guestCurrentDrawing=null;}
  }
  if(state.guestDiceEnabled!==undefined){
    guestDiceEnabled=state.guestDiceEnabled;
    guestDiceThrowEnabled=state.guestDiceThrowEnabled||false;
    updateGuestDicePanel();
    document.getElementById('guestControls')?.style && (document.getElementById('guestControls').style.display='flex');
  }
  if(state.guestInitiativeEnabled!==undefined){
    guestInitiativeEnabled=!!state.guestInitiativeEnabled;
  }
  if(state.bagItems!==undefined)bagItems=normalizeBagItems(state.bagItems);
  if(state.bagWeightMultipliers!==undefined)bagWeightMultipliers=normalizeBagWeightMultipliers(state.bagWeightMultipliers);
  // Apply host custom emotes on guest side
  if(state.customEmotes&&Array.isArray(state.customEmotes)&&state.customEmotes.length===8){
    applyEmoteConfig(state.customEmotes.map(e=>({...e})));
  }
  // Apply host custom enemy emotes on guest side
  if(state.customEnemyEmotes&&Array.isArray(state.customEnemyEmotes)&&state.customEnemyEmotes.length===8){
    applyEnemyEmoteConfig(state.customEnemyEmotes.map(e=>({...e})));
  }
  // Apply overlay from host
  if(state.overlayImageSrc!==undefined){
    applyOverlay(state.overlayImageSrc);
  }
  // Guests always see initiative sidebar; sync sort order
  if(state.initiativeDisplayOrder!==undefined){
    initiativeDisplayOrder=state.initiativeDisplayOrder;
  }
  applyGuestInitiativeVisibility();

  const myTokenIds=participants.filter(p=>p.assignedTo===GUEST_NAME||(p.ownerId&&participants.find(o=>o.id===p.ownerId&&o.assignedTo===GUEST_NAME))).map(p=>p.id);
  if(myTokenIds.length>0){
    if(!localSelection||!myTokenIds.includes(localSelection))localSelection=myTokenIds[0];
    const sel=participants.find(p=>p.id===localSelection);
    guestSelectedInfo.textContent=myTokenIds.length>1?`🎮 ${sel?.publicDisplayName||'Token'} — click others to switch`:`🎮 Assigned: ${sel?.publicDisplayName||'Your token'}`;
  } else if(localSelection&&!participants.find(p=>p.id===localSelection)){
    localSelection=null;guestSelectedInfo.textContent='Click a player token to select it.';
  }

  refreshGuestChargeControls();
  updateTurnBanner(state.publicTurnName);
  checkAndStartAnimLoop();updateRightInitiative();drawAll();renderInventory();
}

/* ================================================================
   ANIMATION
================================================================ */
function hasContinuousTokenAnimation(){
  const now=Date.now();
  return participants.some(p=>p.type==='player')
    || movementAnimations.size>0
    || damageAnimations.size>0
    || performance.now()<screenShakeUntil
    || participants.some(p=>p.pingUntil&&p.pingUntil>now)
    || participants.some(p=>isEmoteActive(p,now)&&isEmoteAnimated(p.emoteKey));
}
function checkAndStartAnimLoop(){if(hasContinuousTokenAnimation())startAnimLoop();}
function startAnimLoop(){
  if(animLoopRunning)return;animLoopRunning=true;
  (function loop(){
    const now=performance.now();
    for(const [id,anim] of movementAnimations){
      if(now-anim.start>=anim.duration)movementAnimations.delete(id);
    }
    for(const [id,anim] of damageAnimations){
      const dmgImg=getPlayerDamageSpriteImage();
      const count=spriteFrameCount(dmgImg);
      if(now-anim.start>=DAMAGE_SPRITE_FRAME_MS*count)damageAnimations.delete(id);
    }
    drawAll();
    if(hasContinuousTokenAnimation())requestAnimationFrame(loop);
    else{animLoopRunning=false;drawAll();}
  })();
}

function easeInOutCubic(t){
  return t<0.5 ? 4*t*t*t : 1-Math.pow(-2*t+2,3)/2;
}

function animateParticipantMove(id,fromX,fromY,toX,toY,duration=1000){
  const participant=participants.find(p=>p.id===id);
  if(participant)setPlayerFacingFromMove(participant,fromX,toX);
  movementAnimations.set(id,{start:performance.now(),duration,fromX,fromY,toX,toY});
  startAnimLoop();
}

function getParticipantDrawPos(p,now=performance.now()){
  const anim=movementAnimations.get(p.id);
  if(!anim)return {x:p.x,y:p.y};
  const t=Math.max(0,Math.min(1,(now-anim.start)/anim.duration));
  if(t>=1){movementAnimations.delete(p.id);return {x:p.x,y:p.y};}
  const e=easeInOutCubic(t);
  return {x:anim.fromX+(anim.toX-anim.fromX)*e,y:anim.fromY+(anim.toY-anim.fromY)*e};
}

