/* ================================================================
   PING EFFECTS (canvas rendering)
================================================================ */
const seenPingIds = new Set();

function rememberPingId(pingId){
  if(!pingId)return true;
  if(seenPingIds.has(pingId))return false;
  seenPingIds.add(pingId);
  setTimeout(()=>seenPingIds.delete(pingId), PING_DISPLAY_MS + 1000);
  return true;
}

function addPingEffect(x,y,pingIndex,label,fromName){
  activePingEffects.push({x,y,pingIndex,label,fromName,startTime:Date.now()});
  startPingAnimLoop();
}

function startPingAnimLoop(){
  if(pingAnimRunning)return;
  pingAnimRunning=true;
  (function loop(){
    drawAll();
    const now=Date.now();
    activePingEffects=activePingEffects.filter(p=>now-p.startTime<PING_DISPLAY_MS);
    if(activePingEffects.length)requestAnimationFrame(loop);
    else{pingAnimRunning=false;drawAll();}
  })();
}

function drawPingEffects(){
  const now=Date.now();
  activePingEffects.forEach(p=>{
    const elapsed=now-p.startTime,t=elapsed/PING_DISPLAY_MS;
    if(t>=1)return;
    const alpha=t<0.12?t/0.12:t>0.72?1-(t-0.72)/0.28:1;
    const scale=t<0.12?0.5+(t/0.12)*0.5:1+t*0.12;
    const sz=58*scale;
    // Image icon — aspect-correct, high quality
    const img=pingImgs[p.pingIndex],pd=PING_DATA[p.pingIndex],asp=pd.w/pd.h;
    const dw=asp>=1?sz:sz*asp, dh=asp>=1?sz/asp:sz;
    if(img.complete){
      ctx.save();
      ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';
      ctx.globalAlpha=alpha;
      ctx.drawImage(img,p.x-dw/2,p.y-dh-5,dw,dh);
      ctx.restore();
    }
    // Label + sender
    ctx.save();ctx.globalAlpha=alpha;
    ctx.font='bold 10px Source Sans 3,sans-serif';ctx.textAlign='center';ctx.textBaseline='alphabetic';
    ctx.fillStyle='#f5a623';ctx.fillText(p.label,p.x,p.y+2);
    ctx.font='9px Source Sans 3,sans-serif';ctx.fillStyle='rgba(255,255,255,0.6)';
    ctx.fillText(p.fromName,p.x,p.y+13);ctx.restore();
  });
}

/* ================================================================
   REMINDER SYSTEM (host-only)
================================================================ */
function toastContainer(){return document.getElementById('reminder-toasts');}

function checkRemindersForTurn(idx){
  if(!isHost)return;
  if(idx===shownReminderTurnIndex)return;
  shownReminderTurnIndex=idx;
  const p=participants[idx];
  if(!p||!p.reminders||!p.reminders.length)return;

  const toRemove=[];
  p.reminders.forEach(r=>{
    const interval=Math.max(1,r.interval||1);
    const instances=r.instances||0; // 0 = unlimited
    const triggerCount=r.triggerCount||0;
    const createdRound=r.createdRound||1;

    // Check if this round is a trigger round for this reminder
    const roundsSinceCreated=roundNumber-createdRound;
    if(roundsSinceCreated<0)return; // Created in a future round somehow
    if(roundsSinceCreated%interval!==0)return; // Not an interval round

    // Check instances
    if(instances>0&&triggerCount>=instances)return; // Exhausted

    // Fire it
    r.triggerCount=(triggerCount+1);
    showReminderToast(p,r);

    // Schedule removal if this was the last instance
    if(instances>0&&r.triggerCount>=instances){
      toRemove.push(r.id);
    }
  });

  if(toRemove.length){
    p.reminders=p.reminders.filter(r=>!toRemove.includes(r.id));
    updateInitiativeList();
    syncToServer();
  }
}

function showReminderToast(p,reminder){
  const color=p.color||(p.type==='player'?'#6366f1':'#e05252');
  const toast=document.createElement('div');toast.className='reminder-toast';
  toast.innerHTML=`
    <div class="toast-header"><div class="toast-dot" style="background:${color}"></div><span>⏰ ${escHtml(p.name)}'s Turn</span></div>
    <div class="toast-body">${escHtml(reminder.text)}</div>
    <button class="toast-dismiss">✕</button>
  `;
  toast.querySelector('.toast-dismiss').addEventListener('click',e=>{e.stopPropagation();dismissToast(toast);});
  const timer=setTimeout(()=>dismissToast(toast),12000);
  toast.dataset.timer=String(timer);
  toastContainer().appendChild(toast);
}

function dismissToast(toast){
  clearTimeout(parseInt(toast.dataset.timer));
  toast.style.transition='opacity .2s,transform .2s';toast.style.opacity='0';toast.style.transform='translateX(30px)';
  setTimeout(()=>toast.remove(),220);
}

function escHtml(s){return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}

function buildReminderUI(p,container){
  const wrapper=document.createElement('div');wrapper.className='ir-reminders';
  wrapper.draggable=false;
  // Block events AND reset draggable on the parent row so inputs don't get hijacked by drag
  wrapper.addEventListener('mousedown',e=>{e.stopPropagation();const r=wrapper.closest('.init-r');if(r)r.draggable=false;});
  wrapper.addEventListener('click',e=>e.stopPropagation());

  function makeReminderForm(existing, onSave, onCancel){
    const form=document.createElement('div');form.className='ir-add-reminder';
    form.draggable=false;
    form.addEventListener('mousedown',e=>{e.stopPropagation();const r=form.closest('.init-r');if(r)r.draggable=false;});
    form.addEventListener('click',e=>e.stopPropagation());

    // Text row
    const topRow=document.createElement('div');topRow.className='ir-add-reminder-row';
    const inp=document.createElement('input');inp.type='text';inp.placeholder='e.g. Roll concentration…';inp.maxLength=80;
    if(existing)inp.value=existing.text;
    topRow.appendChild(inp);

    // Type toggle: Repeating vs One-time
    const typeRow=document.createElement('div');typeRow.className='ir-reminder-type';
    const repBtn=document.createElement('button');repBtn.type='button';repBtn.className='ir-reminder-type-btn';repBtn.textContent='🔄 Repeating';
    const onceBtn=document.createElement('button');onceBtn.type='button';onceBtn.className='ir-reminder-type-btn';onceBtn.textContent='1× One-time';
    let reminderType=(existing&&existing.instances===1)?'once':'repeating';
    function setType(t){
      reminderType=t;
      repBtn.classList.toggle('active-repeating',t==='repeating');
      onceBtn.classList.toggle('active-once',t==='once');
      intervalLabel.textContent=t==='once'?'after':'every';
    }
    repBtn.addEventListener('click',e=>{e.stopPropagation();setType('repeating');});
    onceBtn.addEventListener('click',e=>{e.stopPropagation();setType('once');});
    typeRow.appendChild(repBtn);typeRow.appendChild(onceBtn);

    // Interval row
    const fieldsRow=document.createElement('div');fieldsRow.className='ir-reminder-fields';
    const intervalLabel=document.createElement('span');
    const intInp=document.createElement('input');intInp.type='number';intInp.min='1';intInp.value=existing?existing.interval||1:1;intInp.title='Trigger every N rounds';
    const roundsSuffix=document.createElement('span');roundsSuffix.textContent='rounds';
    fieldsRow.appendChild(intervalLabel);fieldsRow.appendChild(intInp);fieldsRow.appendChild(roundsSuffix);

    // Duration row (only shown for repeating)
    const durRow=document.createElement('div');durRow.className='ir-reminder-fields';durRow.style.marginTop='3px';
    const durLabel=document.createElement('span');durLabel.textContent='for';
    const durInp=document.createElement('input');durInp.type='number';durInp.min='0';durInp.placeholder='∞';durInp.title='Total duration in rounds (0 = unlimited)';
    // Pre-fill if editing and had a finite count
    if(existing&&existing.instances>0&&existing.instances!==1){durInp.value=existing.instances*((existing.interval)||1);}
    else if(existing&&existing.duration){durInp.value=existing.duration;}
    const durSuffix=document.createElement('span');durSuffix.textContent='rounds total (0=∞)';
    const durWrap=document.createElement('div');durWrap.style.display='flex';durWrap.style.flexDirection='column';durWrap.style.gap='3px';
    durRow.appendChild(durLabel);durRow.appendChild(durInp);durRow.appendChild(durSuffix);

    // Helper: calc instances from duration/interval
    function calcInstances(){
      const iv=Math.max(1,parseInt(intInp.value)||1);
      const dur=parseInt(durInp.value)||0;
      return (reminderType==='once')?1:(dur>0?Math.max(1,Math.floor(dur/iv)):0);
    }
    function updateDurHint(){
      const iv=Math.max(1,parseInt(intInp.value)||1);
      const dur=parseInt(durInp.value)||0;
      if(dur>0&&reminderType==='repeating'){
        const procs=Math.max(1,Math.floor(dur/iv));
        durSuffix.textContent=`rounds total → ${procs} proc${procs===1?'':'s'}`;
      } else {
        durSuffix.textContent='rounds total (0=∞)';
      }
    }
    intInp.addEventListener('input',()=>{updateDurHint();e&&e.stopPropagation&&e.stopPropagation();});
    durInp.addEventListener('input',updateDurHint);

    // Show/hide duration row based on type
    function updateDurRowVisibility(){
      durRow.style.display=reminderType==='once'?'none':'flex';
    }

    const origSetType=setType;
    setType=function(t){origSetType(t);updateDurRowVisibility();updateDurHint();};

    // Initialise type display
    setType(reminderType);

    // Block events on all inputs
    [inp,intInp,durInp].forEach(el=>{
      el.addEventListener('mousedown',e=>e.stopPropagation());
      el.addEventListener('click',e=>e.stopPropagation());
      el.addEventListener('keydown',e=>e.stopPropagation());
    });

    // Save / cancel
    const btnRow=document.createElement('div');btnRow.className='ir-add-reminder-row';btnRow.style.justifyContent='flex-end';
    const sv=document.createElement('button');sv.className='btn-success btn-small';sv.textContent=existing?'✓ Save':'✓ Add';
    const cn=document.createElement('button');cn.className='btn-secondary btn-small';cn.textContent='✕';

    const doSave=()=>{
      const txt=inp.value.trim();if(!txt)return;
      const interval=Math.max(1,parseInt(intInp.value)||1);
      const durVal=parseInt(durInp.value)||0;
      const instances=calcInstances();
      onSave(txt,interval,instances,durVal);
    };
    sv.addEventListener('click',e=>{e.stopPropagation();doSave();});
    cn.addEventListener('click',e=>{e.stopPropagation();onCancel();});
    inp.addEventListener('keydown',e=>{if(e.key==='Enter')doSave();if(e.key==='Escape')onCancel();e.stopPropagation();});

    btnRow.appendChild(sv);btnRow.appendChild(cn);
    form.appendChild(topRow);form.appendChild(typeRow);form.appendChild(fieldsRow);form.appendChild(durRow);form.appendChild(btnRow);
    setTimeout(()=>inp.focus(),0);
    return form;
  }

  function refresh(){
    wrapper.innerHTML='';
    const rems=p.reminders||[];

    rems.forEach(r=>{
      const slot=document.createElement('div');
      slot.draggable=false;

      function showRow(){
        slot.innerHTML='';
        const item=document.createElement('div');item.className='ir-reminder-item';

        const textSpan=document.createElement('span');textSpan.className='ir-reminder-text';textSpan.textContent='🔔 '+r.text;

        // Status badge
        const interval=r.interval||1;
        const instances=r.instances||0;
        const triggered=r.triggerCount||0;
        const isOnce=instances===1;
        const status=document.createElement('span');status.className='ir-reminder-status';
        if(isOnce){
          status.textContent=triggered>=1?'✓ done':`1× after ${interval}r`;
          if(triggered>=1)status.classList.add('exhausted');
        } else if(instances>0){
          const remaining=instances-triggered;
          status.textContent=`🔄 every ${interval}r · ${remaining}/${instances} left`;
          if(remaining<=0)status.classList.add('exhausted');
        } else {
          status.textContent=`🔄 every ${interval}r (∞)`;
        }

        const editBtn=document.createElement('button');editBtn.className='ir-reminder-edit-btn';editBtn.textContent='✏️';editBtn.title='Edit reminder';
        editBtn.addEventListener('click',e=>{e.stopPropagation();showEditForm();});

        const del=document.createElement('button');del.className='ir-reminder-del';del.textContent='✕';del.title='Delete reminder';
        del.addEventListener('click',e=>{e.stopPropagation();p.reminders=p.reminders.filter(x=>x.id!==r.id);refresh();syncToServer();});

        item.appendChild(textSpan);item.appendChild(status);item.appendChild(editBtn);item.appendChild(del);
        slot.appendChild(item);
      }

      function showEditForm(){
        slot.innerHTML='';
        const form=makeReminderForm(r,(txt,interval,instances,duration)=>{
          r.text=txt;r.interval=interval;r.instances=instances;r.duration=duration||0;
          syncToServer();showRow();
        },showRow);
        slot.appendChild(form);
      }

      showRow();
      wrapper.appendChild(slot);
    });

    // ＋ Add Reminder button
    const addSlot=document.createElement('div');
    const addBtn=document.createElement('button');addBtn.className='ir-show-add-btn';addBtn.textContent='＋ Reminder';
    addBtn.addEventListener('click',e=>{
      e.stopPropagation();
      addSlot.innerHTML='';
      const form=makeReminderForm(null,(txt,interval,instances,duration)=>{
        if(!p.reminders)p.reminders=[];
        p.reminders.push({
          id:'rem_'+Date.now()+'_'+Math.random().toString(36).slice(2),
          text:txt,interval,instances,duration:duration||0,
          triggerCount:0,createdRound:roundNumber
        });
        syncToServer();refresh();
      },refresh);
      addSlot.appendChild(form);
    });
    addSlot.appendChild(addBtn);
    wrapper.appendChild(addSlot);
  }

  refresh();container.appendChild(wrapper);
}

/* ================================================================
   ITEMS — HOST BUILD UI (inside initiative rows)
================================================================ */
function buildItemsUI(p,container){
  if(!isHost)return;
  const wrapper=document.createElement('div');wrapper.className='ir-items';
  wrapper.draggable=false;
  // Block events AND reset draggable on the parent row so inputs don't get hijacked by drag
  wrapper.addEventListener('mousedown',e=>{e.stopPropagation();const r=wrapper.closest('.init-r');if(r)r.draggable=false;});
  wrapper.addEventListener('click',e=>e.stopPropagation());
  const lbl=document.createElement('div');lbl.className='ir-items-label';lbl.textContent='📦 Items';
  wrapper.appendChild(lbl);

  function buildItemForm(it, onSave, onCancel, submitLabel){
    const form=document.createElement('div');form.className='ir-add-item-form';
    form.draggable=false;
    form.addEventListener('mousedown',e=>{e.stopPropagation();const r=form.closest('.init-r');if(r)r.draggable=false;});
    form.addEventListener('click',e=>e.stopPropagation());
    const nameInp=document.createElement('input');nameInp.placeholder='Item name…';nameInp.maxLength=80;if(it)nameInp.value=it.name;
    const textArea=document.createElement('textarea');textArea.placeholder='Item description / text content…';textArea.rows=3;if(it)textArea.value=it.text||'';
    const visCheck=document.createElement('label');visCheck.className='checkbox';visCheck.style.fontSize='11px';
    const visInp=document.createElement('input');visInp.type='checkbox';visInp.checked=it?it.visible:true;
    visCheck.appendChild(visInp);visCheck.appendChild(document.createTextNode(' Visible to players'));
    const btnRow=document.createElement('div');btnRow.className='ir-add-item-row';
    const saveBtn=document.createElement('button');saveBtn.className='btn-success btn-small';saveBtn.textContent=submitLabel||'✓ Save';
    const cancelBtn=document.createElement('button');cancelBtn.className='btn-secondary btn-small';cancelBtn.textContent='✕';
    const doSave=()=>{const n=nameInp.value.trim();if(!n)return;onSave(n,textArea.value,visInp.checked);};
    saveBtn.addEventListener('click',e=>{e.stopPropagation();doSave();});
    cancelBtn.addEventListener('click',e=>{e.stopPropagation();onCancel();});
    [nameInp,textArea,visInp].forEach(el=>{
      el.addEventListener('mousedown',e=>e.stopPropagation());
      el.addEventListener('click',e=>e.stopPropagation());
    });
    nameInp.addEventListener('keydown',e=>{if(e.key==='Enter')doSave();if(e.key==='Escape')onCancel();e.stopPropagation();});
    textArea.addEventListener('keydown',e=>e.stopPropagation());
    btnRow.appendChild(saveBtn);btnRow.appendChild(cancelBtn);
    form.appendChild(nameInp);form.appendChild(textArea);form.appendChild(visCheck);form.appendChild(btnRow);
    setTimeout(()=>nameInp.focus(),0);
    return form;
  }

  function refresh(){
    // Remove everything except the label
    while(wrapper.children.length>1)wrapper.removeChild(wrapper.lastChild);
    const items=p.items||[];
    items.forEach(it=>{
      // Container holds either the normal row OR an edit form
      const slot=document.createElement('div');
      slot.draggable=false;

      function showRow(){
        slot.innerHTML='';
        const row=document.createElement('div');
        row.className='ir-item-row'+(it.visible?'':' item-hidden');

        const visBtn=document.createElement('button');visBtn.className='ir-item-vis-btn';
        visBtn.title=it.visible?'Visible to players (click to hide)':'Hidden from players (click to show)';
        visBtn.textContent=it.visible?'👁':'🙈';
        visBtn.addEventListener('click',e=>{e.stopPropagation();it.visible=!it.visible;showRow();syncToServer();});

        const nameBtn=document.createElement('button');nameBtn.className='ir-item-name-btn';
        nameBtn.textContent=it.name;nameBtn.title='View / read item';
        nameBtn.addEventListener('click',e=>{e.stopPropagation();openItemViewer(it,p.name);});

        const editBtn=document.createElement('button');editBtn.className='ir-edit-btn';editBtn.textContent='✏️';editBtn.title='Edit item';editBtn.style.cssText='padding:1px 4px;font-size:11px;';
        editBtn.addEventListener('click',e=>{e.stopPropagation();showEditForm();});

        const delBtn=document.createElement('button');delBtn.className='ir-item-del-btn';delBtn.textContent='✕';delBtn.title='Remove item';
        delBtn.addEventListener('click',e=>{
          e.stopPropagation();
          showConfirm(`Remove "${it.name}" from ${p.name}?`,()=>{p.items=p.items.filter(x=>x.id!==it.id);refresh();syncToServer();});
        });

        row.appendChild(visBtn);row.appendChild(nameBtn);row.appendChild(editBtn);row.appendChild(delBtn);
        slot.appendChild(row);
      }

      function showEditForm(){
        slot.innerHTML='';
        const form=buildItemForm(it,(n,txt,vis)=>{
          it.name=n;it.text=txt;it.visible=vis;
          syncToServer();showRow();
        },showRow,'✓ Save');
        slot.appendChild(form);
      }

      showRow();
      wrapper.appendChild(slot);
    });

    // Add-item button
    const addBtn=document.createElement('button');addBtn.className='ir-show-add-item-btn';addBtn.textContent='＋ Add Item';
    addBtn.addEventListener('click',e=>{
      e.stopPropagation();addBtn.style.display='none';
      const form=buildItemForm(null,(n,txt,vis)=>{
        if(!p.items)p.items=[];
        p.items.push({id:'item_'+Date.now()+'_'+Math.random().toString(36).slice(2),name:n,text:txt,visible:vis});
        syncToServer();refresh();
      },refresh,'✓ Add');
      wrapper.appendChild(form);
    });
    wrapper.appendChild(addBtn);
  }

  refresh();
  container.appendChild(wrapper);
}

/* ================================================================
   ITEMS — CONTEXT MENU (right-click on any token)
================================================================ */
let _ctxTarget=null;
const itemCtxMenu=document.getElementById('itemContextMenu');

function showItemContextMenu(p,clientX,clientY){
  _ctxTarget=p;
  const color=p.color||(p.type==='player'?'#6366f1':'#e05252');
  document.getElementById('ctxDot').style.background=color;
  const displayName=isHost?p.name:(p.publicDisplayName||(p.type==='player'?'Player':'Enemy'));
  document.getElementById('ctxName').textContent=displayName;

  const itemList=document.getElementById('ctxItemList');
  itemList.innerHTML='';
  const items=p.items||[];
  // Host sees all; guests see only visible
  const visibleItems=isHost?items:items.filter(it=>it.visible);

  if(!visibleItems.length){
    const empty=document.createElement('div');empty.className='ctx-no-items';
    empty.textContent=isHost?'No items — add below':'No visible items';
    itemList.appendChild(empty);
  } else {
    visibleItems.forEach(it=>{
      const row=document.createElement('div');
      row.className='ctx-item'+((!it.visible&&isHost)?' item-hidden-ctx':'');
      const icon=document.createElement('span');icon.className='ctx-item-icon';
      icon.textContent=it.visible?'📜':'📜';
      const name=document.createElement('span');name.className='ctx-item-name';
      name.textContent=(isHost&&!it.visible?'🙈 ':'')+it.name;
      row.appendChild(icon);row.appendChild(name);
      row.addEventListener('click',()=>{closeItemContextMenu();openItemViewer(it,displayName);});
      itemList.appendChild(row);
    });
  }

  // Actions section
  const actions=document.getElementById('ctxActions');
  actions.innerHTML='';
  if(!isHost){
    // Guest: measure action
    const mAct=document.createElement('div');mAct.className='ctx-action';
    mAct.innerHTML='<span>📏</span><span>Measure from here</span>';
    mAct.addEventListener('click',()=>{
      closeItemContextMenu();
      guestMeasuring={entity:p,active:true,cursorX:p.x,cursorY:p.y};drawAll();
    });
    actions.appendChild(mAct);
    // Nickname for enemies
    if(!p.publicDisplayName){
      const nAct=document.createElement('div');nAct.className='ctx-action';
      nAct.innerHTML='<span>✏️</span><span>Set nickname</span>';
      nAct.addEventListener('click',()=>{
        closeItemContextMenu();
        const alreadyNicked=loadLocalNicknames()[p.id];
        showPrompt(`Set nickname for enemy (blank to clear). Current: "${alreadyNicked||'none'}"`,alreadyNicked||'',(action)=>{
          const map=loadLocalNicknames();if(action.trim()==='')delete map[p.id];else map[p.id]=action.trim();saveLocalNicknames(map);drawAll();
        });
      });
      actions.appendChild(nAct);
    }
  } else {
    // Host: measure & ping
    const mAct=document.createElement('div');mAct.className='ctx-action';
    mAct.innerHTML='<span>📏</span><span>Measure from here</span>';
    mAct.addEventListener('click',()=>{closeItemContextMenu();measuring={entity:p,active:true,cursorX:p.x,cursorY:p.y};drawAll();});
    actions.appendChild(mAct);
    const pAct=document.createElement('div');pAct.className='ctx-action';
    pAct.innerHTML='<span>📍</span><span>Ping token</span>';
    pAct.addEventListener('click',()=>{closeItemContextMenu();p.pingUntil=Date.now()+3000;startAnimLoop();syncToServer();});
    actions.appendChild(pAct);
    const dmgAct=document.createElement('div');dmgAct.className='ctx-action';
    dmgAct.innerHTML='<span>⚔️</span><span>Damage Entity</span>';
    dmgAct.addEventListener('click',()=>{
      closeItemContextMenu();
      const participantId=p.id;
      showPrompt('Damage type? (phys / mill / both):','phys',(dmgType)=>{
        if(!dmgType)return;
        const dt=dmgType.trim().toLowerCase();
        const isMill=dt==='mill';
        const isBoth=dt==='both';
        showPrompt(`Enter ${isBoth?'both':isMill?'mill':'phys'} damage amount:`,'0',(raw)=>{
          const dmg=parseInt(raw,10);
          if(isNaN(dmg)||dmg<=0)return;
          const target=participants.find(pp=>pp.id===participantId);
          if(!target)return;
          const nextAfterDamage=(cur,max)=>Math.max(0,((cur??max??0)|0)-dmg);
          if(isBoth){
            target.hp=nextAfterDamage(target.hp,target.maxHp);
            target.sanity=nextAfterDamage(target.sanity,target.maxSanity);
          } else if(isMill){
            target.sanity=nextAfterDamage(target.sanity,target.maxSanity);
          } else {
            target.hp=nextAfterDamage(target.hp,target.maxHp);
          }
          clearParticipantEmote(target,false);
          if(target.type==='player'){
            damageAnimations.set(target.id,{start:performance.now()});
          }
          screenShakeUntil=performance.now()+350;
          startAnimLoop();
          updateInitiativeList();refreshHpControls();drawAll();syncToServer();
          checkZeroAndOfferRemoval(target);
        });
      });
    });
    actions.appendChild(dmgAct);
    // View Details (wiki data)
    const detAct=document.createElement('div');detAct.className='ctx-action';
    detAct.innerHTML='<span>📖</span><span>View Details</span>';
    detAct.addEventListener('click',()=>{
      closeItemContextMenu();
      openEnemyDetails(p);
    });
    actions.appendChild(detAct);
    // Add Associated Entity
    const addAssocAct=document.createElement('div');addAssocAct.className='ctx-action';
    addAssocAct.innerHTML='<span>🐾</span><span>Add Associated Entity</span>';
    addAssocAct.addEventListener('click',()=>{
      closeItemContextMenu();
      openAssocSpawnModal(p);
    });
    actions.appendChild(addAssocAct);
  }

  // Position & show
  itemCtxMenu.classList.add('open');
  const menuW=220,menuH=itemCtxMenu.offsetHeight||200;
  const x=Math.min(clientX+4,window.innerWidth-menuW-8);
  const y=Math.min(clientY+4,window.innerHeight-menuH-8);
  itemCtxMenu.style.left=x+'px';itemCtxMenu.style.top=y+'px';
}

function closeItemContextMenu(){
  itemCtxMenu.classList.remove('open');_ctxTarget=null;
}

document.addEventListener('mousedown',e=>{
  if(itemCtxMenu.classList.contains('open')&&!itemCtxMenu.contains(e.target))closeItemContextMenu();
  const ccm=document.getElementById('canvasCtxMenu');
  if(ccm&&ccm.style.display!=='none'&&!ccm.contains(e.target))closeCanvasCtxMenu();
});
document.addEventListener('keydown',e=>{
  if(e.key==='Escape'){closeItemContextMenu();closeCanvasCtxMenu();closeWikiTemplateSelector();closeEnemyDetails();}
});

/* ================================================================
   CANVAS EMPTY-SPACE CONTEXT MENU
================================================================ */
const canvasCtxMenu=document.getElementById('canvasCtxMenu');

function showCanvasCtxMenu(clientX, clientY){
  canvasCtxMenu.style.display='block';
  const menuW=200,menuH=canvasCtxMenu.offsetHeight||120;
  const x=Math.min(clientX+4,window.innerWidth-menuW-8);
  const y=Math.min(clientY+4,window.innerHeight-menuH-8);
  canvasCtxMenu.style.left=x+'px';canvasCtxMenu.style.top=y+'px';
}

function closeCanvasCtxMenu(){canvasCtxMenu.style.display='none';}

function spawnParticipant(data){
  participants.push({
    id:'p_'+Date.now()+'_'+Math.floor(Math.random()*1000),
    name:data.name,initiative:data.initiative,type:data.type,
    speed:data.speed,color:data.color,radius:data.radius,
    avatar:'',x:canvasSpawnPos.x,y:canvasSpawnPos.y,
    movedUnits:0,maxHp:data.maxHp,hp:data.maxHp,maxSanity:data.maxSanity,sanity:data.maxSanity,
    maxCharges:MAX_CHARGES,charges:0,chargesTurnStartAdd:0,chargesTurnEndAdd:0,
    assignedTo:null,pingUntil:null,emoteKey:null,emoteUntil:0,items:[]
  });
  updateInitiativeList();renderAssignmentList();drawAll();syncToServer();
}

if(isHost){
  document.getElementById('canvasCtxNewEntity').addEventListener('click',()=>{
    closeCanvasCtxMenu();
    document.getElementById('uiSpawnName').value='New Character';
    document.getElementById('uiSpawnType').value='player';
    document.getElementById('uiSpawnInit').value='0';
    document.getElementById('uiSpawnSpeed').value='30';
    document.getElementById('uiSpawnHp').value='10';
    document.getElementById('uiSpawnModal').style.display='flex';
    setTimeout(()=>{const el=document.getElementById('uiSpawnName');el.focus();el.select();},50);
  });
  document.getElementById('uiSpawnOk').addEventListener('click',()=>{
    const name=document.getElementById('uiSpawnName').value.trim();
    if(!name){showAlert('Enter an entity name.');return;}
    const type=document.getElementById('uiSpawnType').value;
    const ini=parseInt(document.getElementById('uiSpawnInit').value)||0;
    const speed=parseInt(document.getElementById('uiSpawnSpeed').value)||0;
    const maxHpRaw=parseInt(document.getElementById('uiSpawnHp').value);
    const maxHp=isNaN(maxHpRaw)?undefined:maxHpRaw;
    const color=type==='enemy'?'#e05252':'#6366f1';
    document.getElementById('uiSpawnModal').style.display='none';
    spawnParticipant({name,type,initiative:ini,speed,maxHp,color,radius:PARTICLE_RADIUS});
  });
  document.getElementById('uiSpawnCancel').addEventListener('click',()=>{
    document.getElementById('uiSpawnModal').style.display='none';
  });

  document.getElementById('canvasCtxQuickPlayer').addEventListener('click',()=>{
    closeCanvasCtxMenu();
    const num=participants.filter(p=>p.type==='player').length+1;
    spawnParticipant({name:'Player '+num,type:'player',initiative:25,speed:7,maxHp:18,maxSanity:5,color:'#6366f1',radius:PARTICLE_RADIUS});
  });

  document.getElementById('canvasCtxQuickEnemy').addEventListener('click',()=>{
    closeCanvasCtxMenu();
    const num=participants.filter(p=>p.type==='enemy').length+1;
    spawnParticipant({name:'Enemy '+num,type:'enemy',initiative:2,speed:10,maxHp:20,maxSanity:5,color:'#e05252',radius:PARTICLE_RADIUS});
  });

  const fromTemplateBtn=document.getElementById('canvasCtxFromTemplate');
  if(fromTemplateBtn){
    fromTemplateBtn.addEventListener('click',()=>{
      closeCanvasCtxMenu();
      if(!wikiTemplates.length){showAlert('No wiki templates available.');return;}
      openWikiTemplateSelector();
    });
  }
}

/* ================================================================
   ASSOCIATED ENTITIES — spawn, edit, remove
================================================================ */
let _assocOwner=null;
function openAssocSpawnModal(owner){
  _assocOwner=owner;
  document.getElementById('assocOwnerLabel').textContent=owner.name;
  document.getElementById('assocSpawnName').value='';
  document.getElementById('assocSpawnSpeed').value='30';
  document.getElementById('assocSpawnHp').value='5';
  document.getElementById('assocSpawnRadius').value=Math.max(5,Math.round((owner.radius||PARTICLE_RADIUS)*0.7));
  document.getElementById('assocSpawnModal').style.display='flex';
  setTimeout(()=>{const el=document.getElementById('assocSpawnName');el.focus();el.select();},50);
}
if(isHost){
  document.getElementById('assocSpawnOk').addEventListener('click',()=>{
    if(!_assocOwner)return;
    const name=document.getElementById('assocSpawnName').value.trim();
    if(!name){showAlert('Enter a name for the associated entity.');return;}
    const speed=parseInt(document.getElementById('assocSpawnSpeed').value)||0;
    const maxHpRaw=parseInt(document.getElementById('assocSpawnHp').value);
    const maxHp=isNaN(maxHpRaw)?undefined:maxHpRaw;
    const radius=Math.max(5,parseInt(document.getElementById('assocSpawnRadius').value)||10);
    const color=_assocOwner.color||(_assocOwner.type==='player'?'#6366f1':'#e05252');
    participants.push({
      id:'p_'+Date.now()+'_'+Math.floor(Math.random()*1000),
      name,initiative:_assocOwner.initiative,type:_assocOwner.type,
      speed,color,radius,
      avatar:'',x:_assocOwner.x+(_assocOwner.radius||PARTICLE_RADIUS)*2,y:_assocOwner.y,
      movedUnits:0,maxHp,hp:maxHp,maxSanity:undefined,sanity:undefined,
      maxCharges:MAX_CHARGES,charges:0,chargesTurnStartAdd:0,chargesTurnEndAdd:0,
      assignedTo:_assocOwner.assignedTo||null,pingUntil:null,emoteKey:null,emoteUntil:0,items:[],
      ownerId:_assocOwner.id,spriteFacing:1
    });
    document.getElementById('assocSpawnModal').style.display='none';
    _assocOwner=null;
    updateInitiativeList();renderAssignmentList();drawAll();syncToServer();
  });
  document.getElementById('assocSpawnCancel').addEventListener('click',()=>{
    document.getElementById('assocSpawnModal').style.display='none';_assocOwner=null;
  });
}

function getAssociatedEntities(ownerId){
  return participants.filter(p=>p.ownerId===ownerId);
}

function removeAssociatedEntity(p){
  showConfirm(`Remove associated entity "${p.name}"?`,()=>{
    if(measuring&&measuring.entity===p)measuring=null;
    participants=participants.filter(pp=>pp!==p);
    updateInitiativeList();refreshHpControls();drawAll();syncToServer();
  });
}

/* ================================================================
   WIKI TEMPLATES — IMPORT & STORAGE
================================================================ */
let wikiTemplates=[];
(function loadWikiTemplates(){
  const stored=localStorage.getItem('combatWikiTemplates');
  if(stored){try{wikiTemplates=JSON.parse(stored);}catch(e){wikiTemplates=[];}}
  updateWikiTemplateCount();
})();

function saveWikiTemplates(){
  localStorage.setItem('combatWikiTemplates',JSON.stringify(wikiTemplates));
  updateWikiTemplateCount();
}

function updateWikiTemplateCount(){
  const el=document.getElementById('wikiTemplateCount');
  if(el) el.textContent=wikiTemplates.length?`${wikiTemplates.length} template(s) loaded`:'No templates loaded';
}

if(isHost){
  const importWikiBtn=document.getElementById('importWikiBtn');
  const wikiImportFile=document.getElementById('wikiImportFile');

  if(importWikiBtn&&wikiImportFile){
    importWikiBtn.addEventListener('click',()=>{
      wikiImportFile.click();
    });

    wikiImportFile.addEventListener('change',(evt)=>{
    const file=evt.target.files[0];
    if(!file)return;
    const reader=new FileReader();
    reader.onload=(e)=>{
      try{
        const imported=JSON.parse(e.target.result);
        if(!Array.isArray(imported)){showAlert('Invalid file format! Expected a JSON array of enemies.');return;}
        let added=0,updated=0;
        imported.forEach(tmpl=>{
          const idx=wikiTemplates.findIndex(t=>t.name&&tmpl.name&&t.name===tmpl.name);
          if(idx!==-1){wikiTemplates[idx]=tmpl;updated++;}
          else{wikiTemplates.push(tmpl);added++;}
        });
        saveWikiTemplates();
        showAlert(`Import complete: ${added} new, ${updated} updated.`);
      }catch(err){showAlert('Error reading file: '+err.message);}
      };
      reader.readAsText(file);
      evt.target.value='';
    });
  }

  const wikiDropField=document.getElementById('wikiDropField');
  if(wikiDropField){
    const setHover=(on)=>wikiDropField.classList.toggle('drag-over', !!on);

    wikiDropField.addEventListener('dragenter',evt=>{
      evt.preventDefault();
      evt.stopPropagation();
      setHover(true);
      if(evt.dataTransfer) evt.dataTransfer.dropEffect='copy';
    });

    wikiDropField.addEventListener('dragover',evt=>{
      evt.preventDefault();
      evt.stopPropagation();
      setHover(true);
      if(evt.dataTransfer) evt.dataTransfer.dropEffect='copy';
    });

    wikiDropField.addEventListener('dragleave',()=>{
      setHover(false);
    });

    wikiDropField.addEventListener('drop',evt=>{
      evt.preventDefault();
      evt.stopPropagation();
      setHover(false);

      const enemy=normalizeDroppedWikiEnemy(evt.dataTransfer);
      if(!enemy){
        showAlert('Could not read the dropped enemy.');
        return;
      }

      const x=canvas.width/2;
      const y=canvas.height/2;
      spawnFromWikiTemplateAtPosition(enemy, x, y);
    });
  }
}

/* ================================================================
   WIKI TEMPLATES — SELECTOR MODAL
================================================================ */
function openWikiTemplateSelector(){
  const list=document.getElementById('wikiTemplateList');
  if(!list)return;
  list.innerHTML='';
  wikiTemplates.forEach((tmpl,idx)=>{
    const item=document.createElement('div');
    item.className='wiki-template-item';
    const name=document.createElement('div');
    name.className='wiki-template-name';
    name.textContent=tmpl.name||'Unnamed';
    const info=document.createElement('div');
    info.className='wiki-template-info';
    const parts=[];
    if(tmpl.hp)parts.push('HP: '+tmpl.hp);
    if(tmpl.speed)parts.push('Speed: '+tmpl.speed);
    if(tmpl.size)parts.push('Size: '+tmpl.size);
    if(tmpl.type)parts.push(tmpl.type);
    info.textContent=parts.join(' · ')||'No stats';
    item.appendChild(name);
    item.appendChild(info);
    item.addEventListener('click',()=>{
      closeWikiTemplateSelector();
      spawnFromWikiTemplate(tmpl);
    });
    list.appendChild(item);
  });
  const selector=document.getElementById('wikiTemplateSelector');
  if(selector)selector.classList.add('open');
}

function closeWikiTemplateSelector(){
  const selector=document.getElementById('wikiTemplateSelector');
  if(selector)selector.classList.remove('open');
}
const wikiTemplateSelectorClose=document.getElementById('wikiTemplateSelectorClose');
if(wikiTemplateSelectorClose)wikiTemplateSelectorClose.addEventListener('click',closeWikiTemplateSelector);
const wikiTemplateSelectorEl=document.getElementById('wikiTemplateSelector');
if(wikiTemplateSelectorEl)wikiTemplateSelectorEl.addEventListener('click',e=>{if(e.target===wikiTemplateSelectorEl)closeWikiTemplateSelector();});

function parseSizeToRadius(size){
  if(!size)return PARTICLE_RADIUS;
  const num=parseInt(size);
  if(!isNaN(num)&&num>0)return Math.max(5,num);
  const s=size.toLowerCase().trim();
  if(s==='tiny')return 10;
  if(s==='small')return 15;
  if(s==='medium')return PARTICLE_RADIUS;
  if(s==='large')return 35;
  if(s==='huge')return 50;
  if(s==='gargantuan')return 65;
  return PARTICLE_RADIUS;
}

function parseSpeed(speed){
  if(!speed)return 6;
  const num=parseInt(speed);
  if(isNaN(num))return 6;
  // Convert ft to units (assuming 5ft = 1 unit)
  return Math.round(num/5);
}

function parseHp(hp){
  if(!hp)return 20;
  const num=parseInt(hp);
  if(isNaN(num))return 20;
  return num;
}

function spawnFromWikiTemplateAtPosition(tmpl, dropX, dropY){
  const maxHp=parseHp(tmpl.hp);
  const maxSanity=parseHp(tmpl.sanity);
  const speed=parseSpeed(tmpl.speed);
  const radius=parseSizeToRadius(tmpl.size);
  const wikiData={};
  if(tmpl.weaknesses)wikiData.weaknesses=tmpl.weaknesses;
  if(tmpl.resistances)wikiData.resistances=tmpl.resistances;
  if(tmpl.immunities)wikiData.immunities=tmpl.immunities;
  if(tmpl.notes)wikiData.notes=tmpl.notes;
  if(tmpl.tactics)wikiData.tactics=tmpl.tactics;
  if(tmpl.attacks)wikiData.attacks=tmpl.attacks;
  if(tmpl.abilities)wikiData.abilities=tmpl.abilities;
  if(tmpl.type)wikiData.creatureType=tmpl.type;
  if(tmpl.size)wikiData.size=tmpl.size;
  if(tmpl.sanity)wikiData.sanity=tmpl.sanity;
  if(tmpl.drops)wikiData.drops=tmpl.drops;
  if(tmpl.image)wikiData.image=tmpl.image;

  participants.push({
    id:'p_'+Date.now()+'_'+Math.floor(Math.random()*1000),
    name:tmpl.name||'Enemy',initiative:Math.floor(Math.random()*20)+1,type:'enemy',
    speed:speed,color:tmpl.color||'#e05252',radius:radius,
    avatar:tmpl.image || tmpl.sprite || tmpl.avatar || '',
    x:dropX ?? canvasSpawnPos.x,
    y:dropY ?? canvasSpawnPos.y,
    movedUnits:0,maxHp:maxHp,hp:maxHp,maxSanity:tmpl.sanity?maxSanity:undefined,sanity:tmpl.sanity?maxSanity:undefined,
    maxCharges:MAX_CHARGES,charges:0,chargesTurnStartAdd:0,chargesTurnEndAdd:0,
    assignedTo:null,pingUntil:null,items:[],
    wikiData:wikiData
  });
  updateInitiativeList();renderAssignmentList();drawAll();syncToServer();
}

function spawnFromWikiTemplate(tmpl){
  spawnFromWikiTemplateAtPosition(tmpl, canvasSpawnPos.x, canvasSpawnPos.y);
}

// Checks dataTransfer.types (readable during dragenter/dragover) to detect a
// wiki-enemy drag without calling getData(), which browsers block at that stage.
function looksLikeWikiEnemyDrag(evt){
  if(!evt||!evt.dataTransfer) return false;
  const types=Array.from(evt.dataTransfer.types||[]);
  return types.includes('application/x-ttrpg-enemy')||types.includes('application/json');
}

function normalizeDroppedWikiEnemy(dataTransfer){
  if(!dataTransfer) return null;

  const tryParse = (raw) => {
    if(!raw) return null;
    const text = String(raw).trim();
    if(!text) return null;
    try {
      const parsed = JSON.parse(text);
      return parsed && typeof parsed === 'object' ? parsed : null;
    } catch {
      return null;
    }
  };

  const collectRawValues = () => {
    const values = [];
    const push = (v) => {
      if(v === undefined || v === null) return;
      const s = String(v);
      if(!s.trim()) return;
      if(!values.includes(s)) values.push(s);
    };

    // Preferred custom payloads
    push(dataTransfer.getData('application/x-ttrpg-enemy'));
    push(dataTransfer.getData('application/json'));

    // Browser-friendly fallbacks
    push(dataTransfer.getData('text/plain'));
    push(dataTransfer.getData('text/uri-list'));
    push(dataTransfer.getData('text/html'));

    // Some drag sources expose types but don't surface them in the usual slots
    try{
      const types = Array.from(dataTransfer.types || []);
      for(const type of types){
        if(typeof type !== 'string') continue;
        const raw = dataTransfer.getData(type);
        push(raw);
      }
    }catch{}
    return values;
  };

  const rawValues = collectRawValues();

  // First, try anything that looks like JSON
  for(const raw of rawValues){
    const parsed = tryParse(raw);
    if(parsed) return parsed;
  }

  // Then plain text fallbacks
  const plain = rawValues.find(v => String(v).trim())?.trim() || '';
  if(!plain) return null;

  // If plain text is a known name, resolve it from cached templates or saved wiki data.
  const matchesName = (arr) => Array.isArray(arr)
    ? arr.find(t => String(t?.name || '').trim() === plain)
    : null;

  const cached = matchesName(combatWikiTemplates);
  if(cached) return cached;

  try{
    const stored = localStorage.getItem('combatWikiTemplates');
    if(stored){
      const parsed = JSON.parse(stored);
      const match = matchesName(parsed);
      if(match) return match;
    }
  }catch{}

  // Fallback to the old wiki storage key too, so older setups still work.
  try{
    const oldStored = localStorage.getItem('dndEnemies');
    if(oldStored){
      const parsed = JSON.parse(oldStored);
      const match = matchesName(parsed);
      if(match) return match;
    }
  }catch{}

  // Last resort: spawn a basic enemy using the dropped text as the name.
  return { name: plain };
}

/* ================================================================
   INVENTORY BAGS + WIKI ITEMS
================================================================ */
function normalizeBagItems(items){
  const src=Array.isArray(items)?items:[];
  return src.map(it=>{
    const loc=it?.location&&typeof it.location==='object'?it.location:{};
    const kind=loc.kind==='canvas'?'canvas':(loc.kind==='slot'?'slot':'bag');
    const bagId=(String(loc.bagId||'fin').toLowerCase());
    const slotId=(String(loc.slotId||'head').toLowerCase());
    return {
      id:it?.id||('bag_'+Date.now()+'_'+Math.random().toString(36).slice(2)),
      name:String(it?.name||'Item'),
      type:String(it?.type||''),
      weight:Number.isFinite(Number(it?.weight))?Number(it.weight):0,
      size:it?.size===undefined?'medium':it.size,
      description:String(it?.description||it?.text||''),
      image:String(it?.image||it?.sprite||''),
      visible:it?.visible!==false,
      location:{
        kind:kind==='slot'?'slot':kind,
        bagId:(bagId==='nad'||bagId==='kat'?bagId:'fin'),
        slotId:kind==='slot'?(INVENTORY_SLOT_IDS.includes(slotId)?slotId:'head'):null,
        x:Number.isFinite(Number(loc.x))?Number(loc.x):40,
        y:Number.isFinite(Number(loc.y))?Number(loc.y):40,
      },
    };
  });
}

function normalizeBagWeightMultipliers(raw){
  const src=raw&&typeof raw==='object'?raw:{};
  const clamp=(v)=>{
    const n=Number(v);
    if(!Number.isFinite(n))return 0;
    return Math.max(0,Math.min(100,n));
  };
  return {
    fin:clamp(src.fin),
    nad:clamp(src.nad),
    kat:clamp(src.kat),
  };
}

function looksLikeWikiItemDrag(evt){
  if(!evt||!evt.dataTransfer)return false;
  const types=Array.from(evt.dataTransfer.types||[]);
  return types.includes('application/x-ttrpg-item');
}

function normalizeDroppedWikiItem(dataTransfer){
  if(!dataTransfer)return null;
  const tryParse=(raw)=>{
    if(!raw)return null;
    try{const p=JSON.parse(String(raw));return p&&typeof p==='object'?p:null;}catch{return null;}
  };
  const direct=tryParse(dataTransfer.getData('application/x-ttrpg-item'));
  if(direct)return direct;
  const maybeJson=tryParse(dataTransfer.getData('application/json'));
  if(maybeJson&&(maybeJson.weight!==undefined||maybeJson.description!==undefined||maybeJson.type!==undefined))return maybeJson;
  return null;
}

function itemPixelSize(item){
  const numeric=parseInt(String(item?.size??'40').trim(),10);
  if(Number.isFinite(numeric)&&numeric>0)return Math.max(14,Math.min(260,numeric));
  return 40;
}

function inventoryItemPassesFilter(item){
  const byName=!inventoryFilters.name||item.name.toLowerCase().includes(inventoryFilters.name);
  const byType=!inventoryFilters.type||String(item.type||'').toLowerCase().includes(inventoryFilters.type);
  const minW=inventoryFilters.minWeight===''?null:Number(inventoryFilters.minWeight);
  const maxW=inventoryFilters.maxWeight===''?null:Number(inventoryFilters.maxWeight);
  const w=Number(item.weight)||0;
  const byMin=minW===null||w>=minW;
  const byMax=maxW===null||w<=maxW;
  return byName&&byType&&byMin&&byMax;
}

function addBagItemFromTemplate(tmpl,targetKind,targetPos){
  const target=targetPos&&typeof targetPos==='object'?targetPos:{};
  const kind=targetKind==='canvas'?'canvas':(targetKind==='slot'?'slot':'bag');
  const slotId=String(target.slotId||'head').toLowerCase();
  const bagIdRaw=String(target.bagId||'fin').toLowerCase();
  const bagId=(bagIdRaw==='nad'||bagIdRaw==='kat')?bagIdRaw:'fin';
  const item={
    id:'bag_'+Date.now()+'_'+Math.random().toString(36).slice(2),
    name:String(tmpl.name||'Item'),
    type:String(tmpl.type||''),
    weight:Number.isFinite(Number(tmpl.weight))?Number(tmpl.weight):0,
    size:tmpl.size===undefined?'medium':tmpl.size,
    description:String(tmpl.description||tmpl.text||''),
    image:String(tmpl.image||tmpl.sprite||''),
    visible:true,
    location:{
      kind,
      bagId,
      slotId:kind==='slot'?(INVENTORY_SLOT_IDS.includes(slotId)?slotId:'head'):null,
      x:Number.isFinite(Number(target.x))?Number(target.x):40,
      y:Number.isFinite(Number(target.y))?Number(target.y):40,
    },
  };

  if(item.location.kind==='slot'&&bagItems.some(it=>it.id!==item.id&&it.location?.kind==='slot'&&it.location?.slotId===item.location.slotId&&it.location?.bagId===item.location.bagId)){
    showAlert('This slot already has an item.');
    return;
  }

  bagItems.push(item);
  if(isHost)syncToServer();
  renderInventory();
  drawAll();
}

function setBagItemLocation(itemId,location){
  const idx=bagItems.findIndex(it=>it.id===itemId);
  if(idx===-1)return;
  const item=bagItems[idx];
  const incoming=location&&typeof location==='object'?location:{};
  const kind=incoming.kind==='canvas'?'canvas':(incoming.kind==='slot'?'slot':'bag');
  const slotId=String(incoming.slotId||'head').toLowerCase();
  const bagId=String(incoming.bagId||'fin').toLowerCase();
  const normalizedBagId=(bagId==='nad'||bagId==='kat')?bagId:'fin';
  const nextLocation={
    kind,
    bagId:normalizedBagId,
    slotId:kind==='slot'?(INVENTORY_SLOT_IDS.includes(slotId)?slotId:'head'):null,
    x:Number.isFinite(Number(incoming.x))?Number(incoming.x):40,
    y:Number.isFinite(Number(incoming.y))?Number(incoming.y):40,
  };

  if(nextLocation.kind==='slot'){
    const occupied=bagItems.find(it=>it.id!==itemId&&it.location?.kind==='slot'&&it.location?.slotId===nextLocation.slotId&&it.location?.bagId===nextLocation.bagId);
    if(occupied){
      showAlert('This slot already has an item.');
      renderInventory();
      drawAll();
      return;
    }
  }

  bagItems[idx]={...item,location:nextLocation};
  if(isHost){
    syncToServer();
  }else{
    send({type:'guest_bag_item_move',itemId,location:nextLocation});
  }
  renderInventory();
  drawAll();
}

function removeBagItem(itemId){
  bagItems=bagItems.filter(it=>it.id!==itemId);
  if(isHost)syncToServer();
  renderInventory();
  drawAll();
}

function inventoryCanvasToScreen(x,y){
  const rect=canvas.getBoundingClientRect();
  return {x:(x/canvas.width)*rect.width,y:(y/canvas.height)*rect.height};
}

function inventoryScreenToCanvas(clientX,clientY){
  const rect=canvas.getBoundingClientRect();
  return {
    x:((clientX-rect.left)/rect.width)*canvas.width,
    y:((clientY-rect.top)/rect.height)*canvas.height,
  };
}

function inventorySlotWellId(bagId,slotId){
  return `invSlot-${bagId}-${slotId}`;
}

function startInvDrag(itemId,evt){
  evt.preventDefault();
  evt.stopPropagation();
  draggingInvItem={itemId};
  const item=bagItems.find(it=>it.id===itemId);
  if(!item)return;
  const body=document.body;
  const panel=document.getElementById('top-inventory');
  const panelIcon=document.getElementById('inv-toggle-icon');
  let autoOpened=false;

  const onMove=(e)=>{
    const kind=item.location?.kind;
    const fromBagId=item?.location?.bagId||'fin';
    const fromSlotId=item?.location?.slotId||'head';
    const slotEl=document.getElementById(inventorySlotWellId(fromBagId,fromSlotId));
    const surface=document.getElementById(`invBag${fromBagId.charAt(0).toUpperCase()+fromBagId.slice(1)}`);
    const layer=document.getElementById('item-layer');
    if(!draggingInvItem)return;
    const node=document.querySelector(`.inv-item-sprite[data-item-id="${itemId}"]`);
    if(!node)return;
    node.classList.add('dragging');
    node.style.transform='none';

    const pr=panel.getBoundingClientRect();
    const hoveringPanel=e.clientX>=pr.left&&e.clientX<=pr.right&&e.clientY>=pr.top&&e.clientY<=pr.bottom;
    if(hoveringPanel&&!panel.classList.contains('open')){
      panel.classList.add('open');
      panelIcon.textContent='▲';
      autoOpened=true;
    }else if(autoOpened&&!hoveringPanel){
      panel.classList.remove('open');
      panelIcon.textContent='▼';
      autoOpened=false;
    }

    if(kind==='bag'&&surface){
      const r=surface.getBoundingClientRect();
      node.style.left=(e.clientX-r.left-node.offsetWidth/2)+'px';
      node.style.top=(e.clientY-r.top-node.offsetHeight/2)+'px';
    }else if(kind==='slot'&&slotEl){
      const r=slotEl.getBoundingClientRect();
      node.style.left=(e.clientX-r.left-node.offsetWidth/2)+'px';
      node.style.top=(e.clientY-r.top-node.offsetHeight/2)+'px';
    }else{
      const r=layer.getBoundingClientRect();
      node.style.left=(e.clientX-r.left-node.offsetWidth/2)+'px';
      node.style.top=(e.clientY-r.top-node.offsetHeight/2)+'px';
    }
  };
  const onUp=(e)=>{
    const originKind=item.location?.kind;
    const deleteZone=document.getElementById('inv-delete-zone');
    const canvasRect=canvas.getBoundingClientRect();
    const delRect=deleteZone.getBoundingClientRect();
    const panelOpen=panel.classList.contains('open');
    let targetBag=null;
    let targetSlot=null;

    if(panelOpen){
      BAG_IDS.forEach(bagId=>{
        if(targetBag)return;
        const el=document.getElementById(`invBag${bagId.charAt(0).toUpperCase()+bagId.slice(1)}`);
        if(!el)return;
        const r=el.getBoundingClientRect();
        if(e.clientX>=r.left&&e.clientX<=r.right&&e.clientY>=r.top&&e.clientY<=r.bottom){
          targetBag={id:bagId,rect:r};
        }
      });

      BAG_IDS.forEach(bagId=>{
        if(targetSlot)return;
        INVENTORY_SLOT_DEFS.forEach(slot=>{
          if(targetSlot)return;
          const el=document.getElementById(inventorySlotWellId(bagId,slot.id));
          if(!el)return;
          const r=el.getBoundingClientRect();
          if(e.clientX>=r.left&&e.clientX<=r.right&&e.clientY>=r.top&&e.clientY<=r.bottom){
            targetSlot={id:slot.id,bagId};
          }
        });
      });
    }

    const inDelete=e.clientX>=delRect.left&&e.clientX<=delRect.right&&e.clientY>=delRect.top&&e.clientY<=delRect.bottom;
    const inBag=!!targetBag;
    const inSlot=!!targetSlot;
    const inCanvas=e.clientX>=canvasRect.left&&e.clientX<=canvasRect.right&&e.clientY>=canvasRect.top&&e.clientY<=canvasRect.bottom;

    if(inDelete&&isHost){
      removeBagItem(itemId);
    }else if(inSlot){
      setBagItemLocation(itemId,{kind:'slot',bagId:targetSlot.bagId,slotId:targetSlot.id,x:0,y:0});
    }else if(inBag){
      setBagItemLocation(itemId,{kind:'bag',bagId:targetBag.id,x:e.clientX-targetBag.rect.left,y:e.clientY-targetBag.rect.top});
    }else if(inCanvas){
      const c=inventoryScreenToCanvas(e.clientX,e.clientY);
      setBagItemLocation(itemId,{kind:'canvas',bagId:item.location?.bagId||'fin',x:c.x,y:c.y});
    }else{
      renderInventory();
      drawAll();
    }

    if(originKind==='bag'&&(!inBag||inCanvas||inDelete||inSlot)){
      panel.classList.remove('open');
      panelIcon.textContent='▼';
      autoOpened=false;
    }else if(autoOpened){
      panel.classList.remove('open');
      panelIcon.textContent='▼';
      autoOpened=false;
    }

    draggingInvItem=null;
    body.removeEventListener('mousemove',onMove);
    body.removeEventListener('mouseup',onUp);
  };
  body.addEventListener('mousemove',onMove);
  body.addEventListener('mouseup',onUp);
}

function renderInventory(){
  BAG_IDS.forEach(bagId=>{
    const suffix=bagId.charAt(0).toUpperCase()+bagId.slice(1);
    const surface=document.getElementById(`invBag${suffix}`);
    const weightEl=document.getElementById(`invWeight${suffix}`);
    const mulInput=document.getElementById(`invMul${suffix}`);
    if(!surface||!weightEl)return;
    if(mulInput){
      const val=Math.max(0,Math.min(100,Number(bagWeightMultipliers[bagId])||0));
      if(String(val)!==mulInput.value)mulInput.value=String(val);
      mulInput.disabled=!isHost;
    }
    surface.innerHTML='';

    const bagItemsInBag=bagItems.filter(it=>it.location.kind==='bag'&&it.location.bagId===bagId);
    const bagVisible=bagItemsInBag.filter(inventoryItemPassesFilter);

    bagVisible.forEach(item=>{
      const size=itemPixelSize(item);
      const el=document.createElement('div');
      el.className='inv-item-sprite';
      el.dataset.itemId=item.id;
      el.style.width=size+'px';
      el.style.height=size+'px';
      el.style.left=(item.location.x||20)+'px';
      el.style.top=(item.location.y||20)+'px';
      if(item.image)el.style.backgroundImage=`url("${item.image}")`;
      el.title=`${item.name} (${Math.round(Number(item.weight)||0)} Kg)`;
      el.addEventListener('mousedown',evt=>startInvDrag(item.id,evt));
      el.addEventListener('contextmenu',evt=>{
        evt.preventDefault();
        openInventoryItemViewer(item);
      });
      surface.appendChild(el);
    });

    renderInventorySlots(bagId);

    const bagRaw=bagItemsInBag.reduce((sum,it)=>sum+(Number(it.weight)||0),0);
    const reduction=Math.max(0,Math.min(100,Number(bagWeightMultipliers[bagId])||0));
    const bagAdjusted=bagRaw*(1-(reduction/100));
    const slotsRaw=bagItems.filter(it=>it.location.kind==='slot'&&it.location.bagId===bagId).reduce((sum,it)=>sum+(Number(it.weight)||0),0);
    const total=bagAdjusted+slotsRaw;
    weightEl.textContent=`Total: ${Math.round(total)} Kg`;
  });

  renderCanvasInventoryLayer();
}

function renderInventorySlots(bagId){
  const suffix=bagId.charAt(0).toUpperCase()+bagId.slice(1);
  const wrap=document.getElementById(`invSlots${suffix}`);
  if(!wrap)return;
  wrap.innerHTML='';

  INVENTORY_SLOT_DEFS.forEach(slot=>{
    const slotBox=document.createElement('div');
    slotBox.className='inv-slot';

    const label=document.createElement('div');
    label.className='inv-slot-label';
    label.textContent=slot.label;

    const well=document.createElement('div');
    well.className='inv-slot-well';
    well.dataset.bag=bagId;
    well.dataset.slot=slot.id;
    well.id=inventorySlotWellId(bagId,slot.id);
    if(isHost){
      well.addEventListener('dragover',evt=>{
        if(looksLikeWikiItemDrag(evt)){evt.preventDefault();evt.dataTransfer.dropEffect='copy';well.classList.add('drag-over');}
      });
      well.addEventListener('dragleave',()=>well.classList.remove('drag-over'));
      well.addEventListener('drop',evt=>{
        well.classList.remove('drag-over');
        const tmpl=normalizeDroppedWikiItem(evt.dataTransfer);
        if(!tmpl)return;
        evt.preventDefault();
        addBagItemFromTemplate(tmpl,'slot',{bagId,slotId:slot.id,x:0,y:0});
        syncToServer();
      });
    }

    const item=bagItems.find(it=>it.location.kind==='slot'&&it.location.bagId===bagId&&it.location.slotId===slot.id&&inventoryItemPassesFilter(it));
    if(item){
      const el=document.createElement('div');
      const size=Math.max(20,Math.min(30,itemPixelSize(item)));
      el.className='inv-item-sprite';
      el.dataset.itemId=item.id;
      el.style.width=size+'px';
      el.style.height=size+'px';
      el.style.left='50%';
      el.style.top='50%';
      el.style.transform='translate(-50%, -50%)';
      if(item.image)el.style.backgroundImage=`url("${item.image}")`;
      el.title=`${item.name} (${(Number(item.weight)||0).toFixed(1)} Kg)`;
      el.addEventListener('mousedown',evt=>startInvDrag(item.id,evt));
      el.addEventListener('contextmenu',evt=>{
        evt.preventDefault();
        openInventoryItemViewer(item);
      });
      well.appendChild(el);
    }

    slotBox.appendChild(label);
    slotBox.appendChild(well);
    wrap.appendChild(slotBox);
  });
}

function renderCanvasInventoryLayer(){
  const layer=document.getElementById('item-layer');
  if(!layer)return;
  layer.innerHTML='';
  const list=bagItems.filter(it=>it.location.kind==='canvas'&&inventoryItemPassesFilter(it));
  list.forEach(item=>{
    const size=itemPixelSize(item);
    const pos=inventoryCanvasToScreen(item.location.x||40,item.location.y||40);
    const el=document.createElement('div');
    el.className='inv-item-sprite';
    el.dataset.itemId=item.id;
    el.style.width=size+'px';
    el.style.height=size+'px';
    el.style.left=(pos.x-size/2)+'px';
    el.style.top=(pos.y-size/2)+'px';
    if(item.image)el.style.backgroundImage=`url("${item.image}")`;
    el.title=`${item.name} (${(Number(item.weight)||0).toFixed(1)} Kg)`;
    el.addEventListener('mousedown',evt=>startInvDrag(item.id,evt));
    el.addEventListener('contextmenu',evt=>{
      evt.preventDefault();
      openInventoryItemViewer(item);
    });
    layer.appendChild(el);
  });
}

function openInventoryItemViewer(item){
  const details=[];
  details.push(`<div><strong>Type:</strong> ${escHtml(String(item.type||'-'))}</div>`);
  details.push(`<div><strong>Weight:</strong> ${(Number(item.weight)||0).toFixed(1)} Kg</div>`);
  details.push(`<div><strong>Size:</strong> ${escHtml(String(item.size||'medium'))}</div>`);
  if(item.description)details.push(`<div style="margin-top:8px;white-space:pre-wrap">${escHtml(item.description)}</div>`);
  const img=item.image?`<div style="margin-bottom:8px"><div style="width:120px;height:120px;border-radius:10px;background:#111827 center/cover no-repeat;border:1px solid rgba(255,255,255,.15);background-image:url('${escHtml(item.image)}')"></div></div>`:'';
  openItemViewer({name:item.name,_html:img+details.join('')},'Inventory');
}

function loadWikiItemTemplates(){
  try{wikiItemTemplates=JSON.parse(localStorage.getItem('combatWikiItemTemplates')||'[]');}catch{wikiItemTemplates=[];}
  updateWikiItemsCount();
  renderWikiItems();
}

function saveWikiItemTemplates(){
  localStorage.setItem('combatWikiItemTemplates',JSON.stringify(wikiItemTemplates));
  updateWikiItemsCount();
  renderWikiItems();
}

function updateWikiItemsCount(){
  const el=document.getElementById('wikiItemsCount');
  if(el)el.textContent=wikiItemTemplates.length?`${wikiItemTemplates.length} item template(s)`:'No item templates loaded';
}

function renderWikiItems(){
  const list=document.getElementById('wikiItemList');
  if(!list)return;
  list.innerHTML='';
  wikiItemTemplates.forEach(tmpl=>{
    const card=document.createElement('div');
    card.className='wiki-item-card';
    card.draggable=true;
    card.innerHTML=`
      <div class="wiki-item-thumb" style="${tmpl.image?`background-image:url('${escHtml(tmpl.image)}')`:''}"></div>
      <div class="wiki-item-meta">
        <div class="wiki-item-name">${escHtml(String(tmpl.name||'Item'))}</div>
        <div class="wiki-item-info">${escHtml(String(tmpl.type||'type'))} · ${(Number(tmpl.weight)||0).toFixed(1)} Kg</div>
      </div>
    `;
    card.addEventListener('dragstart',evt=>{
      evt.dataTransfer.setData('application/x-ttrpg-item',JSON.stringify(tmpl));
      evt.dataTransfer.effectAllowed='copy';
    });
    card.addEventListener('contextmenu',evt=>{
      evt.preventDefault();
      openInventoryItemViewer(normalizeBagItems([{...tmpl,location:{kind:'bag',bagId:'fin',x:20,y:20}}])[0]);
    });
    list.appendChild(card);
  });
}

function initInventoryUI(){
  loadWikiItemTemplates();
  bagItems=normalizeBagItems(bagItems);

  const panel=document.getElementById('top-inventory');
  const handle=document.getElementById('inv-handle');
  const icon=document.getElementById('inv-toggle-icon');
  handle.addEventListener('click',()=>{
    panel.classList.toggle('open');
    icon.textContent=panel.classList.contains('open')?'▲':'▼';
  });

  const del=document.getElementById('inv-delete-zone');
  if(isHost)del.classList.add('host-visible');

  const filterName=document.getElementById('invFilterName');
  const filterType=document.getElementById('invFilterType');
  const minW=document.getElementById('invFilterMinWeight');
  const maxW=document.getElementById('invFilterMaxWeight');
  [filterName,filterType,minW,maxW].forEach(el=>{
    el.addEventListener('input',()=>{
      inventoryFilters={
        name:filterName.value.trim().toLowerCase(),
        type:filterType.value.trim().toLowerCase(),
        minWeight:minW.value,
        maxWeight:maxW.value,
      };
      renderInventory();
    });
  });

  BAG_IDS.forEach(bagId=>{
    const suffix=bagId.charAt(0).toUpperCase()+bagId.slice(1);
    const bagSurface=document.getElementById(`invBag${suffix}`);
    if(!bagSurface)return;

    bagSurface.addEventListener('dragover',evt=>{
      if(!isHost)return;
      if(looksLikeWikiItemDrag(evt)){evt.preventDefault();evt.dataTransfer.dropEffect='copy';bagSurface.classList.add('drag-over');}
    });
    bagSurface.addEventListener('dragleave',()=>bagSurface.classList.remove('drag-over'));
    bagSurface.addEventListener('drop',evt=>{
      bagSurface.classList.remove('drag-over');
      if(!isHost)return;
      const tmpl=normalizeDroppedWikiItem(evt.dataTransfer);
      if(!tmpl)return;
      evt.preventDefault();
      const r=bagSurface.getBoundingClientRect();
      addBagItemFromTemplate(tmpl,'bag',{bagId,x:evt.clientX-r.left,y:evt.clientY-r.top});
      syncToServer();
    });
  });

  BAG_IDS.forEach(bagId=>{
    const suffix=bagId.charAt(0).toUpperCase()+bagId.slice(1);
    const input=document.getElementById(`invMul${suffix}`);
    if(!input)return;
    input.value=String(Number(bagWeightMultipliers[bagId])||0);
    input.addEventListener('input',()=>{
      bagWeightMultipliers[bagId]=Math.max(0,Math.min(100,Number(input.value)||0));
      renderInventory();
      if(isHost)syncToServer();
    });
  });

  const deleteZone=document.getElementById('inv-delete-zone');
  deleteZone.addEventListener('dragover',evt=>{
    if(!isHost)return;
    evt.preventDefault();
    deleteZone.classList.add('drag-over');
  });
  deleteZone.addEventListener('dragleave',()=>deleteZone.classList.remove('drag-over'));
  deleteZone.addEventListener('drop',evt=>{evt.preventDefault();deleteZone.classList.remove('drag-over');});

  const addBtn=document.getElementById('addWikiItemBtn');
  const importBtn=document.getElementById('importWikiItemsBtn');
  const exportBtn=document.getElementById('exportWikiItemsBtn');
  const importInput=document.getElementById('wikiItemsImportFile');
  const modal=document.getElementById('itemCreatorModal');

  if(!isHost){
    [addBtn,importBtn,exportBtn].forEach(btn=>{if(btn)btn.style.display='none';});
  }

  addBtn?.addEventListener('click',()=>modal.classList.add('open'));
  document.getElementById('itemCreatorCancel')?.addEventListener('click',()=>modal.classList.remove('open'));
  document.getElementById('itemCreatorSave')?.addEventListener('click',()=>{
    const tmpl={
      name:document.getElementById('newItemName').value.trim()||'Item',
      type:document.getElementById('newItemType').value.trim(),
      weight:Number(document.getElementById('newItemWeight').value)||0,
      size:document.getElementById('newItemSize').value.trim()||'medium',
      image:document.getElementById('newItemImage').value.trim(),
      description:document.getElementById('newItemDescription').value.trim(),
    };
    wikiItemTemplates.push(tmpl);
    saveWikiItemTemplates();
    modal.classList.remove('open');
  });

  importBtn?.addEventListener('click',()=>importInput.click());
  importInput?.addEventListener('change',evt=>{
    const file=evt.target.files?.[0];
    if(!file)return;
    const reader=new FileReader();
    reader.onload=(e)=>{
      try{
        const parsed=JSON.parse(String(e.target.result||'[]'));
        if(!Array.isArray(parsed)){showAlert('Invalid item file format.');return;}
        wikiItemTemplates=parsed.map(it=>({
          name:String(it?.name||'Item'),
          type:String(it?.type||''),
          weight:Number(it?.weight)||0,
          size:it?.size===undefined?'medium':it.size,
          image:String(it?.image||it?.sprite||''),
          description:String(it?.description||it?.text||''),
        }));
        saveWikiItemTemplates();
      }catch{showAlert('Could not import item templates.');}
    };
    reader.readAsText(file);
    evt.target.value='';
  });

  exportBtn?.addEventListener('click',()=>{
    const blob=new Blob([JSON.stringify(wikiItemTemplates,null,2)],{type:'application/json'});
    const a=document.createElement('a');
    a.href=URL.createObjectURL(blob);
    a.download='wiki-items.json';
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(()=>URL.revokeObjectURL(a.href),0);
  });

  renderInventory();
}

