function openItemViewer(item,ownerName){
  document.getElementById('itemViewerTitle').textContent=item.name;
  document.getElementById('itemViewerOwner').textContent=`Carried by: ${ownerName}`;
  const body=document.getElementById('itemViewerBody');
  if(item&&item._html!==undefined)body.innerHTML=item._html;
  else body.textContent=item.text||'(No description)';
  document.getElementById('itemViewerModal').classList.add('open');
}
function closeItemViewer(){
  document.getElementById('itemViewerModal').classList.remove('open');
}

/* ================================================================
   ENEMY DETAILS — VIEWER MODAL (host only)
================================================================ */
function openEnemyDetails(p){
  const data=p.wikiData||{};
  document.getElementById('enemyDetailsTitle').textContent=p.name||'Unknown';
  const subtitleParts=[];
  if(data.size)subtitleParts.push(data.size);
  if(data.creatureType)subtitleParts.push(data.creatureType);
  document.getElementById('enemyDetailsSubtitle').textContent=subtitleParts.join(' · ')||'Enemy';

  const body=document.getElementById('enemyDetailsBody');
  const imageSrc=data.image||p.avatar||'';
  body.innerHTML=imageSrc
    ? `<div style="display:flex;justify-content:center;margin-bottom:14px">
         <div style="width:128px;height:128px;border-radius:18px;border:2px solid rgba(245,166,35,.75);background:#0f172a center/cover no-repeat;box-shadow:inset 0 0 0 1px rgba(255,255,255,.06);background-image:url(&quot;${escapeHtml(imageSrc)}&quot;)"></div>
       </div>`
    : '';
  const sections=[
    {key:'weaknesses',title:'Weaknesses',cls:'weaknesses'},
    {key:'resistances',title:'Resistances',cls:'resistances'},
    {key:'immunities',title:'Immunities',cls:'immunities'},
    {key:'attacks',title:'Attacks',cls:'tactics'},
    {key:'abilities',title:'Special Abilities',cls:'tactics'},
    {key:'drops',title:'Drops',cls:'notes'},
    {key:'tactics',title:'Tactics / Behavior',cls:'tactics'},
    {key:'notes',title:'Notes',cls:'notes'},
  ];
  let hasContent=false;
  sections.forEach(sec=>{
    if(data[sec.key]){
      hasContent=true;
      const div=document.createElement('div');div.className='detail-section';
      const title=document.createElement('div');title.className='detail-section-title '+sec.cls;
      title.textContent=sec.title;
      const text=document.createElement('div');text.className='detail-section-text';
      text.textContent=data[sec.key];
      div.appendChild(title);div.appendChild(text);
      body.appendChild(div);
    }
  });
  if(!hasContent){
    body.innerHTML='<div style=\"color:var(--text-muted);text-align:center;padding:20px\">No wiki details available for this entity.<br>Import enemy templates from the Wiki to see details here.</div>';
  }
  document.getElementById('enemyDetailsModal').classList.add('open');
}
function closeEnemyDetails(){
  document.getElementById('enemyDetailsModal').classList.remove('open');
}
document.getElementById('enemyDetailsClose').addEventListener('click',closeEnemyDetails);
document.getElementById('enemyDetailsModal').addEventListener('click',e=>{if(e.target===document.getElementById('enemyDetailsModal'))closeEnemyDetails();});

